/**
 * CP17 — the no-surveillance guarantee, checked against the real records.
 *
 * The promise is structural, not a setting you can flip: this module never
 * *tracks* anything, it *proves* that nothing here could. Three things are
 * guaranteed absent by construction —
 *   - no location: no coordinate, no map, no "where the other parent is".
 *   - no read receipts on the other parent: the ticks on a handover are mutual
 *     confirmations either side records, never a signal that they opened a thing.
 *   - no activity feed: nothing logs "what they did" for the other to watch.
 *
 * `scanForSurveillance` is the teeth. It reads every field name present on every
 * record and flags any that looks like location, a read-receipt, or an activity
 * timestamp. Today it always returns empty — the record shapes carry no such
 * field. Its job is the future: the day someone adds `latitude` or `lastSeen` to
 * a `cp_` record, the test goes red and the guarantee is defended before ship.
 *
 * No copy here: guarantees are message keys the component renders.
 */

import type { CoparentRecord } from './types'

/** The three promises, in display order, as keys the screen translates. */
export const SURVEILLANCE_GUARANTEES = [
  'coparenting.privacy.noLocation',
  'coparenting.privacy.noReadReceipt',
  'coparenting.privacy.noActivityFeed',
] as const

/**
 * Field-name fragments that would betray a guarantee if any record carried one.
 * Matched case-insensitively against field names only — never against values, so
 * a parent typing "lokasi" into a free-text place field is their own note, not a
 * tracked coordinate. Kept deliberately broad on the surveillance vocabulary and
 * checked against every current field name in a test, so it flags a leak without
 * false-positiving on the shapes that ship today.
 */
const FORBIDDEN_FIELD =
  /(location|latitude|longitude|coordinate|geoloc|(^|_)gps|(^|_)(lat|lng|lon)($|_)|readreceipt|readat|seenat|lastseen|lastactive|onlineat|activityfeed|viewedby|trackedat|whereabouts)/i

export interface Leak {
  kind: string
  field: string
}

/** Every field name, across every record, that matches the surveillance denylist. */
export function scanForSurveillance(records: readonly CoparentRecord[]): Leak[] {
  const out: Leak[] = []
  for (const r of records) {
    for (const field of Object.keys(r)) {
      if (FORBIDDEN_FIELD.test(field)) out.push({ kind: r.kind, field })
    }
  }
  return out
}

/** True when nothing in the given records could be read as tracking. */
export function isSurveillanceFree(records: readonly CoparentRecord[]): boolean {
  return scanForSurveillance(records).length === 0
}
