/**
 * Solo Mode (CP5) and parallel parenting (CP6).
 *
 * Both are the same kind of decision — *how much of the other parent is in this
 * screen* — so they live in one tiny module rather than being sprinkled through
 * the components as `if (partner)` checks.
 *
 * Solo Mode is not a degraded mode. Caregivers are labels, not profiles, so
 * every record already works with nobody else attached. What Solo Mode changes
 * is the *waiting*: a screen must never park a record in a state whose only
 * exit is somebody who has not installed the app. So a schedule change you make
 * alone is recorded as agreed, and the statuses that would otherwise read
 * "waiting for an answer" say the thing that is actually true — you have not
 * written down the answer yet.
 *
 * No copy here: every function returns a message key or a plain value.
 */

import type { SwapStatus } from './schedule'
import type { TopicStatus } from './types'

export interface Mode {
  /** No partner profile is paired on this device. The other parent may still exist. */
  solo: boolean
  /** Contact must stay minimal: structured fields only, no free-text channel. */
  parallel: boolean
}

export function modeOf(hasPartner: boolean, parallel: boolean): Mode {
  return { solo: !hasPartner, parallel }
}

// ---------------------------------------------------------------------------
// CP5 — nothing waits on somebody who is not here
// ---------------------------------------------------------------------------

/**
 * The status a newly created swap starts in.
 *
 * Alone, "I ask, they answer" has no second half, so a request would sit at
 * "waiting" forever. What the user is actually doing is recording a change to
 * their own plan, and the schedule should reflect it immediately.
 */
export function newSwapStatus(m: Mode): SwapStatus {
  return m.solo ? 'disetujui' : 'diajukan'
}

/** Statuses whose normal copy points at the other parent. */
const WAITING: { swap: readonly SwapStatus[]; topic: readonly TopicStatus[] } = {
  swap: ['diajukan', 'ditawar'],
  topic: ['diajukan'],
}

/**
 * True when this record is parked on an answer that has to come from outside
 * the app. In Solo Mode that is never true — the only person who can move it is
 * the user, so the copy has to say so.
 */
export function isWaitingOnOther(group: 'swap' | 'topic', status: string, m: Mode): boolean {
  if (m.solo) return false
  return (WAITING[group] as readonly string[]).includes(status)
}

/**
 * Message key for a status chip. Solo Mode swaps in its own wording for exactly
 * the statuses that would otherwise dangle; everything else is untouched.
 */
export function statusKey(group: 'swap' | 'topic', status: string, m: Mode): string {
  const dangling = m.solo && (WAITING[group] as readonly string[]).includes(status)
  return dangling
    ? `coparenting.${group}.status.solo.${status}`
    : `coparenting.${group}.status.${status}`
}

// ---------------------------------------------------------------------------
// CP6 — minimal shared surface
// ---------------------------------------------------------------------------

/**
 * Every free-text box in this module that one parent writes and the other reads.
 *
 * The line drawn here: a box is a *channel* when it carries one adult's words to
 * the other adult. Those go in parallel mode. The handover slots (what the child
 * ate, slept, brought) stay, because they are short factual fields about the
 * child with a fixed label, which is what "structured fields only" means — the
 * point of parallel parenting is that the child keeps getting handed over
 * properly while the adults stop talking.
 */
export const FREE_TEXT_FIELDS = [
  'swapNote',
  'expenseNote',
  'actualNote',
  'childNote',
  'topicText',
  'healthNote',
] as const
export type FreeTextField = (typeof FREE_TEXT_FIELDS)[number]

/**
 * Fields that are not a shared surface at all, so parallel mode has no reason
 * to touch them. The health record is C4 and private by default (CP8): a note in
 * it is the owner talking to themselves.
 */
const OWNER_ONLY: readonly FreeTextField[] = ['healthNote']

export function allowsFreeText(field: FreeTextField, m: Mode): boolean {
  return !m.parallel || OWNER_ONLY.includes(field)
}

/** Parallel mode replaces the free-text matter with a picked request. */
export function structuredTopicOnly(m: Mode): boolean {
  return m.parallel
}
