/**
 * Shared decisions log (CP12): what was agreed, when, by whom — append-only.
 *
 * Append-only is enforced at the edges, not here: the screen offers no edit and
 * no delete, so a logged decision is a fact the record keeps. This module only
 * orders the log and buckets it by month. No copy — category and who-agreed come
 * back as keys the component translates.
 */

import type { CaregiverKey } from './schedule'

/** Who the record says agreed. `berdua` is both; a single side is also honest. */
export type DecidedBy = CaregiverKey | 'berdua'
export const DECIDED_BY: readonly DecidedBy[] = ['aku', 'dia', 'berdua']

export interface DecisionLike {
  /** yyyy-MM-dd the thing was agreed. */
  date: string
  /** Tie-break for two decisions logged on the same day. */
  createdAt: string
}

/** Newest first: by agreed date, then by when it was written down. Never mutates. */
export function sortDecisions<T extends DecisionLike>(rows: readonly T[]): T[] {
  return [...rows].sort(
    (a, b) => b.date.localeCompare(a.date) || b.createdAt.localeCompare(a.createdAt),
  )
}

/** yyyy-MM, for the month headers a long log grows into. */
export function decisionMonth(date: string): string {
  return date.slice(0, 7)
}
