/**
 * Handover confirmation (CP2).
 *
 * A handover card is the core object of this module, so the question "did both
 * sides actually see this?" has to be answerable — and answerable *without*
 * turning a half-ticked card into an accusation.
 *
 * Two rules shape everything here:
 *
 * 1. **Unconfirmed is a normal state.** A card nobody ticked is not late, not
 *    ignored, and not evidence. The state is reported; no one is named as the
 *    party who failed to act.
 * 2. **The copy names who *did* tick, never who did not.** `confirmedBy` drives
 *    the partial message. `missing` exists only so the screen knows which tick
 *    buttons still have something to do.
 *
 * No copy lives here — every function returns message keys or plain data, per
 * the i18n rule.
 */

import { CAREGIVERS, type CaregiverKey } from './schedule'

export interface HandoverLike {
  date: string
  /** HH:mm, optional. */
  time?: string
  confirmedByAku?: string
  confirmedByDia?: string
}

export type ConfirmState = 'both' | 'partial' | 'none'

export interface Confirmation {
  state: ConfirmState
  /** Sides that ticked, in caregiver order. Drives the visible sentence. */
  confirmedBy: CaregiverKey[]
  /** Sides with a tick button still to press. Never rendered as a complaint. */
  missing: CaregiverKey[]
  /** Message key for the neutral one-line status. */
  key: string
}

const FIELD: Record<CaregiverKey, 'confirmedByAku' | 'confirmedByDia'> = {
  aku: 'confirmedByAku',
  dia: 'confirmedByDia',
}

/** Truthy check on purpose: an empty string is not a confirmation. */
export function confirmedAt(h: HandoverLike, who: CaregiverKey): string | undefined {
  return h[FIELD[who]] || undefined
}

export function confirmState(h: HandoverLike): Confirmation {
  const confirmedBy = CAREGIVERS.filter((c) => confirmedAt(h, c))
  const missing = CAREGIVERS.filter((c) => !confirmedAt(h, c))
  const state: ConfirmState = missing.length === 0 ? 'both' : confirmedBy.length === 0 ? 'none' : 'partial'
  return { state, confirmedBy: [...confirmedBy], missing: [...missing], key: `coparenting.ho.confirm.${state}` }
}

/**
 * The patch that ticks or un-ticks one side.
 *
 * Un-ticking is allowed because a mis-tap on somebody else's behalf is the most
 * likely error here, and a confirmation you cannot take back is worse than one
 * you can. `undefined` clears the field in Dexie's `update`.
 */
export function toggleConfirm(
  h: HandoverLike,
  who: CaregiverKey,
  at: string,
): Record<string, string | undefined> {
  return { [FIELD[who]]: confirmedAt(h, who) ? undefined : at }
}

/** Cards not yet ticked by both sides. A count, never a ranking. */
export function countUnconfirmed(list: readonly HandoverLike[]): number {
  return list.filter((h) => confirmState(h).state !== 'both').length
}

/**
 * Newest first, by day *and* clock time.
 *
 * Two handovers on one day is the normal case for a 2-2-3 week (morning drop,
 * evening pick-up), so date alone would put them in whatever order Dexie
 * happened to return. Cards without a time sort to the start of their day.
 */
export function sortHandovers<T extends HandoverLike>(list: readonly T[]): T[] {
  const at = (h: HandoverLike) => `${h.date} ${normalTime(h.time) ?? '00:00'}`
  return [...list].sort((a, b) => at(b).localeCompare(at(a)))
}

/**
 * HH:mm or nothing.
 *
 * `<input type="time">` gives us HH:mm, but a restored backup or a hand-edited
 * row can carry "9:30", "09:30:00" or junk, and a bad string here would silently
 * reorder the list.
 */
export function normalTime(raw: string | undefined): string | undefined {
  const m = /^(\d{1,2}):(\d{2})(?::\d{2})?$/.exec((raw ?? '').trim())
  if (!m) return undefined
  const h = Number(m[1])
  const min = Number(m[2])
  if (h > 23 || min > 59) return undefined
  return `${String(h).padStart(2, '0')}:${String(min).padStart(2, '0')}`
}
