/**
 * Co-parenting maths: rota expansion, swaps, planned-vs-actual, money split.
 *
 * No copy lives here — functions return message keys or plain numbers, per the
 * i18n rule. Nothing here scores a parent: `reconcile` reports what happened on
 * both sides and refuses to rank them.
 */

/**
 * Caregivers are *labels*, not profile ids.
 *
 * This is what makes Solo Mode work: the other parent may never install the app,
 * never have a profile, and never consent to anything. 'dia' is a slot the owner
 * fills with a display name in settings, so every screen is fully usable alone.
 */
export type CaregiverKey = 'aku' | 'dia'

export const CAREGIVERS: readonly CaregiverKey[] = ['aku', 'dia']

export function otherCaregiver(c: CaregiverKey): CaregiverKey {
  return c === 'aku' ? 'dia' : 'aku'
}

/** A repeating rota of arbitrary length. 2-2-3 is one row in here, not the model. */
export interface Rota {
  /** yyyy-MM-dd the cycle counts from. */
  anchorDate: string
  /** One caregiver per day of the cycle. Length is free — 3, 7, 14, 30, anything. */
  days: CaregiverKey[]
}

export type SwapStatus = 'diajukan' | 'ditawar' | 'disetujui' | 'ditolak'

export interface SwapLike {
  /** The day being asked for, or the first day of an exception. */
  date: string
  /**
   * Last day of a multi-day exception. Present means "these days do not follow
   * the pattern" rather than "these two days trade", which is why it wins over
   * `counterDate`: a week away from home has no single day to give back.
   */
  untilDate?: string
  /** Set when the answer was a counter-proposal: the two days trade caregivers. */
  counterDate?: string
  /** Who asked. Used only to say who holds a multi-day exception. */
  askedBy?: CaregiverKey
  status: SwapStatus
}

/** True for a request that covers more than the one day it names. */
export function isRange(s: SwapLike): boolean {
  return typeof s.untilDate === 'string' && s.untilDate > s.date
}

function covers(s: SwapLike, date: string): boolean {
  return date >= s.date && date <= (s.untilDate ?? s.date)
}

export interface ActualLike {
  date: string
  caregiver: CaregiverKey
  /** Optional. Hours are only summed over days that actually carry a number. */
  hours?: number
}

const DAY_MS = 86_400_000

/** Parsed as UTC midnight on purpose: local parsing makes DST days 23 or 25 h. */
function utc(date: string): number {
  return Date.parse(`${date}T00:00:00Z`)
}

export function dayDiff(from: string, to: string): number {
  return Math.round((utc(to) - utc(from)) / DAY_MS)
}

export function addDays(date: string, n: number): string {
  return new Date(utc(date) + n * DAY_MS).toISOString().slice(0, 10)
}

/**
 * Today as yyyy-MM-dd in the *local* calendar.
 *
 * `new Date().toISOString().slice(0,10)` would be UTC, which is the previous day
 * for the first seven hours of every Indonesian morning — a handover card would
 * get filed under yesterday.
 */
export function todayISO(now = new Date()): string {
  const p = (n: number) => String(n).padStart(2, '0')
  return `${now.getFullYear()}-${p(now.getMonth() + 1)}-${p(now.getDate())}`
}

/** Who the rota says has the child, ignoring swaps. */
export function plannedFor(rota: Rota, date: string): CaregiverKey | undefined {
  const n = rota.days.length
  if (n === 0) return undefined
  const diff = dayDiff(rota.anchorDate, date)
  if (!Number.isFinite(diff)) return undefined
  // JS `%` keeps the sign of the dividend, so a date before the anchor would
  // index backwards off the array. The double modulo is what lets the user
  // browse history as well as the future.
  return rota.days[((diff % n) + n) % n]
}

/**
 * Who actually has the child once agreed swaps are applied.
 *
 * A swap with no `counterDate` hands that single day to the other caregiver.
 * A swap with one trades the two days. A request with an `untilDate` is a
 * multi-day exception and gives every covered day to whoever asked. Only
 * `disetujui` swaps move anybody — an unanswered request must never quietly
 * change the plan.
 */
export function effectiveFor(rota: Rota, swaps: SwapLike[], date: string): CaregiverKey | undefined {
  const base = plannedFor(rota, date)
  if (!base) return undefined
  let result = base
  // Applied in array order; two agreed swaps touching the same day stack, with
  // the last one winning. Rare enough that a resolution UI would be overkill.
  for (const s of swaps) {
    if (s.status !== 'disetujui') continue
    if (isRange(s)) {
      // A whole stretch of days goes to whoever asked for it. Flipping day by
      // day would hand half the trip back to the other side, which is never
      // what "I have them for Lebaran week" means.
      if (covers(s, date)) result = s.askedBy ?? otherCaregiver(result)
      continue
    }
    if (s.counterDate) {
      if (date === s.date) result = plannedFor(rota, s.counterDate) ?? result
      else if (date === s.counterDate) result = plannedFor(rota, s.date) ?? result
    } else if (date === s.date) {
      result = otherCaregiver(result)
    }
  }
  return result
}

export interface PlanDay {
  date: string
  planned: CaregiverKey
  effective: CaregiverKey
  swapped: boolean
}

/** Inclusive range. Capped so a typo'd year cannot lock the UI thread. */
export function expand(rota: Rota, swaps: SwapLike[], from: string, days: number): PlanDay[] {
  const out: PlanDay[] = []
  const n = Math.max(0, Math.min(Math.trunc(days), 366))
  for (let i = 0; i < n; i++) {
    const date = addDays(from, i)
    const planned = plannedFor(rota, date)
    const effective = effectiveFor(rota, swaps, date)
    if (!planned || !effective) break
    out.push({ date, planned, effective, swapped: planned !== effective })
  }
  return out
}

export interface Reconciliation {
  /** Days compared — only dates that carry an actual log. */
  compared: number
  /** Planned days in range that were never logged. Reported, never penalised. */
  unlogged: number
  days: Record<CaregiverKey, { planned: number; actual: number }>
  hours: Record<CaregiverKey, number>
  /** Dates where the log differs from the plan. Facts, not fault. */
  different: string[]
}

/**
 * Planned vs actual.
 *
 * Deliberately compared only over days that have a log. Counting unlogged days
 * as "actual: nobody" would turn a forgotten entry into evidence against a
 * parent, which is exactly the thing this module must not produce.
 */
export function reconcile(plan: PlanDay[], actuals: ActualLike[]): Reconciliation {
  const byDate = new Map(actuals.map((a) => [a.date, a]))
  const days: Reconciliation['days'] = { aku: { planned: 0, actual: 0 }, dia: { planned: 0, actual: 0 } }
  const hours: Reconciliation['hours'] = { aku: 0, dia: 0 }
  const different: string[] = []
  let compared = 0
  let unlogged = 0

  for (const d of plan) {
    const a = byDate.get(d.date)
    if (!a) {
      unlogged++
      continue
    }
    compared++
    days[d.effective].planned++
    days[a.caregiver].actual++
    if (Number.isFinite(a.hours) && (a.hours ?? 0) > 0) hours[a.caregiver] += a.hours as number
    if (a.caregiver !== d.effective) different.push(d.date)
  }

  return { compared, unlogged, days, hours, different }
}

// ---------------------------------------------------------------------------
// Money
// ---------------------------------------------------------------------------

export type ExpenseStatus = 'diajukan' | 'disetujui' | 'dibayar' | 'disengketakan'

export interface ExpenseLike {
  amount: number
  /** My share of the cost, 0..1. 0.5 is an even split. */
  myShare: number
  paidBy: CaregiverKey
  status: ExpenseStatus
}

/** Rupiah has no cents here. The remainder lands on the other side so the two
 *  halves always add back up to the original amount exactly. */
export function splitAmount(amount: number, myShare: number): { mine: number; theirs: number } {
  const total = Number.isFinite(amount) && amount > 0 ? Math.round(amount) : 0
  const share = Number.isFinite(myShare) ? Math.min(1, Math.max(0, myShare)) : 0.5
  const mine = Math.round(total * share)
  return { mine, theirs: total - mine }
}

export interface Ledger {
  owedToMe: number
  owedByMe: number
  /** Positive: they owe me. Negative: I owe them. */
  net: number
  disputed: number
  proposed: number
}

/**
 * A running personal record, not an invoice.
 *
 * Only agreed-but-unpaid items move the balance. Disputed and merely-proposed
 * amounts are reported separately so nothing is silently treated as owed.
 */
export function ledger(rows: ExpenseLike[]): Ledger {
  let owedToMe = 0
  let owedByMe = 0
  let disputed = 0
  let proposed = 0

  for (const r of rows) {
    const { mine, theirs } = splitAmount(r.amount, r.myShare)
    if (r.status === 'disengketakan') {
      disputed += r.paidBy === 'aku' ? theirs : mine
      continue
    }
    if (r.status === 'diajukan') {
      proposed += r.paidBy === 'aku' ? theirs : mine
      continue
    }
    if (r.status !== 'disetujui') continue // 'dibayar' is settled
    if (r.paidBy === 'aku') owedToMe += theirs
    else owedByMe += mine
  }

  return { owedToMe, owedByMe, net: owedToMe - owedByMe, disputed, proposed }
}

