const rep = (c: CaregiverKey, n: number): CaregiverKey[] => Array.from({ length: n }, () => c)

/**
 * Starting shapes, not the model. The user can edit any of them day by day, and
 * an empty rota is a valid state — a shape nobody agreed to is worse than none.
 */
export const ROTA_PRESETS: { key: string; days: CaregiverKey[] }[] = [
  {
    key: 'coparenting.rota.223',
    days: ['aku', 'aku', 'dia', 'dia', 'aku', 'aku', 'aku', 'dia', 'dia', 'aku', 'aku', 'dia', 'dia', 'dia'],
  },
  { key: 'coparenting.rota.alt7', days: [...rep('aku', 7), ...rep('dia', 7)] },
  { key: 'coparenting.rota.alt14', days: [...rep('aku', 14), ...rep('dia', 14)] },
  { key: 'coparenting.rota.weekday', days: [...rep('aku', 5), ...rep('dia', 2)] },
  { key: 'coparenting.rota.altDay', days: ['aku', 'dia'] },
]
