/**
 * CP18 — the domain summary, and the coverage guard behind it.
 *
 * The summary is a plain count of what this household has recorded, grouped the
 * way the tabs are, with the most recent activity date. It describes; it never
 * ranks a parent and never scores the pair — a bigger number is not a better
 * parent, it is just more notes.
 *
 * Coverage has two halves, both defended here:
 *   - **Backup/restore.** Every `cp_` record lives in the `family` store, which
 *     is already in `OWNED_STORES` and already covered by `db/backup.ts` (it
 *     asserts only `kind` on `family`). So co-parenting data travels with a
 *     normal export/restore with no change to `backup.ts` — proven by a
 *     round-trip test through `parseBackup`.
 *   - **Summary completeness.** `CP_KINDS` is forced exhaustive at compile time
 *     (see `_exhaustive` below): add a kind to the union and forget it here, and
 *     the typecheck fails. `summarize` also counts any un-grouped record into
 *     `uncovered`, so a missed grouping shows up at runtime too.
 *
 * No copy: group keys are message keys the component renders.
 */

import type { CoparentKind, CoparentRecord } from './types'

/** Every co-parenting kind. Forced complete against the union just below. */
export const CP_KINDS = [
  'child',
  'cp_child_change',
  'cp_health',
  'cp_health_entry',
  'cp_rota',
  'cp_swap',
  'cp_actual',
  'cp_handover',
  'cp_cal',
  'cp_expense',
  'cp_reimburse',
  'cp_topic',
  'cp_contact',
  'cp_decision',
  'cp_thirdparty',
] as const satisfies readonly CoparentKind[]

// Compile-time exhaustiveness: if a new CoparentKind is added and not listed in
// CP_KINDS, `Missing` stops being `never` and this assignment fails to typecheck.
type Missing = Exclude<CoparentKind, (typeof CP_KINDS)[number]>
const _exhaustive: [Missing] extends [never] ? true : Missing = true
void _exhaustive

/** The tab groupings, in display order. Every kind belongs to exactly one. */
export const SUMMARY_GROUPS = [
  { key: 'child', kinds: ['child', 'cp_child_change'] },
  { key: 'health', kinds: ['cp_health', 'cp_health_entry'] },
  { key: 'schedule', kinds: ['cp_rota', 'cp_swap', 'cp_actual'] },
  { key: 'handover', kinds: ['cp_handover'] },
  { key: 'cal', kinds: ['cp_cal'] },
  { key: 'money', kinds: ['cp_expense', 'cp_reimburse'] },
  { key: 'topic', kinds: ['cp_topic'] },
  { key: 'contact', kinds: ['cp_contact'] },
  { key: 'decision', kinds: ['cp_decision'] },
  { key: 'access', kinds: ['cp_thirdparty'] },
] as const satisfies readonly { key: string; kinds: readonly CoparentKind[] }[]

const GROUP_OF: Record<string, string> = {}
for (const g of SUMMARY_GROUPS) for (const k of g.kinds) GROUP_OF[k] = g.key

export interface GroupSummary {
  key: string
  count: number
  /** Most recent `updatedAt` in the group, ISO — undefined when the group is empty. */
  lastUpdated?: string
}

export interface DomainSummary {
  groups: GroupSummary[]
  total: number
  /** Most recent `updatedAt` across everything, ISO. */
  lastActivity?: string
  /** Records whose kind matched no group. A coverage guard — always 0 in practice. */
  uncovered: number
}

const newer = (a: string | undefined, b: string): string => (a && a >= b ? a : b)

/**
 * Count records per group and find the latest activity. Soft-deleted rows are
 * ignored so the summary matches what the screens actually show (`readable`
 * already drops them; this keeps the pure function honest when called directly).
 */
export function summarize(records: readonly CoparentRecord[]): DomainSummary {
  const counts: Record<string, number> = {}
  const last: Record<string, string | undefined> = {}
  let total = 0
  let uncovered = 0
  let lastActivity: string | undefined

  for (const r of records) {
    if (r.deletedAt) continue
    const group = GROUP_OF[r.kind]
    if (!group) {
      uncovered++
      continue
    }
    counts[group] = (counts[group] ?? 0) + 1
    last[group] = newer(last[group], r.updatedAt)
    lastActivity = newer(lastActivity, r.updatedAt)
    total++
  }

  const groups = SUMMARY_GROUPS.map((g) => ({
    key: g.key,
    count: counts[g.key] ?? 0,
    ...(last[g.key] ? { lastUpdated: last[g.key] } : {}),
  }))

  return { groups, total, ...(lastActivity ? { lastActivity } : {}), uncovered }
}
