/**
 * Child-cost splitting (CP10) and reimbursement requests (CP11).
 *
 * CP10's "link to the finance domain split engine" is literal: `childSplit`
 * reuses `distribute`/`incomeWeights` from finance/money, so a child cost is
 * divided by exactly the same largest-remainder maths the household money screen
 * uses, and the two halves always sum back to the amount. Nothing new invents a
 * split rule; this is the finance engine pointed at two caregiver labels.
 *
 * CP11 is a request to be paid back for a cost one side already carried: it names
 * a receipt (by reference, never a stored file) and moves through an
 * accept/decline flow. No copy here — statuses and totals are values and keys.
 */

import { distribute, incomeWeights } from '@/features/finance/money'
import { otherCaregiver, type CaregiverKey } from './schedule'

// ---------------------------------------------------------------------------
// CP10 — split a child cost through the finance engine
// ---------------------------------------------------------------------------

/** How to divide a cost. `rata` is even; `penghasilan` is by each side's income. */
export type SplitBasis = 'rata' | 'penghasilan'
export const SPLIT_BASES: readonly SplitBasis[] = ['rata', 'penghasilan']

/**
 * Split `amount` between the two caregivers via the finance split engine.
 *
 * `rata` weights both sides equally; `penghasilan` weights by declared monthly
 * income (a side with no income entered weighs zero, and if neither entered one
 * `distribute` falls back to even rather than dividing by nothing). The result
 * is guaranteed to sum back to `Math.round(amount)`.
 */
export function childSplit(
  amount: number,
  basis: SplitBasis,
  incomes?: Partial<Record<CaregiverKey, number>>,
): Record<CaregiverKey, number> {
  const weights =
    basis === 'penghasilan'
      ? incomeWeights(['aku', 'dia'], incomes as Record<string, number> | undefined)
      : { aku: 1, dia: 1 }
  const out = distribute(amount, weights)
  return { aku: out.aku ?? 0, dia: out.dia ?? 0 }
}

/**
 * What the *other* side owes when `requestedBy` carried the whole cost: their
 * share of the split. This is the figure a reimbursement request suggests, not a
 * figure it commits anyone to — the other side still accepts or declines.
 */
export function suggestedReimbursement(
  amount: number,
  basis: SplitBasis,
  requestedBy: CaregiverKey,
  incomes?: Partial<Record<CaregiverKey, number>>,
): number {
  return childSplit(amount, basis, incomes)[otherCaregiver(requestedBy)]
}

// ---------------------------------------------------------------------------
// CP11 — reimbursement requests
// ---------------------------------------------------------------------------

/** diajukan → diterima/ditolak (accept/decline) → dibayar once actually settled. */
export type ReimburseStatus = 'diajukan' | 'diterima' | 'ditolak' | 'dibayar'
export const REIMBURSE_STATUSES: readonly ReimburseStatus[] = [
  'diajukan',
  'diterima',
  'ditolak',
  'dibayar',
]

export interface ReimburseLike {
  amount: number
  requestedBy: CaregiverKey
  status: ReimburseStatus
}

/** Only a still-open request can be accepted or declined. */
export function canDecide(r: ReimburseLike): boolean {
  return r.status === 'diajukan'
}

export interface ReimburseTotals {
  /** They asked me to pay them back and I have not answered yet. */
  incomingPending: number
  /** I asked them and they have not answered yet. */
  outgoingPending: number
  /** Accepted, mine to collect (I asked, they agreed, not yet paid). */
  owedToMe: number
  /** Accepted, mine to pay (they asked, I agreed, not yet paid). */
  owedByMe: number
  /** owedToMe − owedByMe. Positive means they still owe me. */
  net: number
}

/**
 * A running personal tally from the owner's ('aku') point of view.
 *
 * Declined ('ditolak') and settled ('dibayar') requests move nothing — only
 * open and accepted amounts count, and pending is reported apart from owed so
 * nothing unanswered is silently treated as a debt.
 */
export function reimburseTotals(rows: readonly ReimburseLike[]): ReimburseTotals {
  const t: ReimburseTotals = {
    incomingPending: 0,
    outgoingPending: 0,
    owedToMe: 0,
    owedByMe: 0,
    net: 0,
  }
  for (const r of rows) {
    const amt = Math.max(0, Math.round(r.amount))
    if (r.status === 'diajukan') {
      if (r.requestedBy === 'aku') t.outgoingPending += amt
      else t.incomingPending += amt
    } else if (r.status === 'diterima') {
      if (r.requestedBy === 'aku') t.owedToMe += amt
      else t.owedByMe += amt
    }
  }
  t.net = t.owedToMe - t.owedByMe
  return t
}
