/**
 * Communication log (CP13): records *that* contact happened, never its content.
 *
 * The record has no free-text body on purpose — the type simply cannot hold a
 * message, a transcript, or a paraphrase. What it holds is the fact of a contact:
 * when, over what channel, who reached out, and whether it connected. That is
 * enough to show "we spoke twice this week" without the app ever becoming a place
 * where one parent's words about the other get stored and re-read.
 *
 * No copy here — the channel comes back as a key the component translates.
 */

export type ContactChannel = 'telepon' | 'chat' | 'tatap_muka' | 'video' | 'surat' | 'lainnya'
export const CONTACT_CHANNELS: readonly ContactChannel[] = [
  'telepon',
  'chat',
  'tatap_muka',
  'video',
  'surat',
  'lainnya',
]

export interface ContactLike {
  /** yyyy-MM-dd the contact happened. */
  date: string
  /** Local clock time, HH:mm. Optional — "some time that day" is honest too. */
  time?: string
  /** Tie-break for two entries logged on the same day with no time. */
  createdAt: string
}

/** Newest first: by day, then clock time, then when it was written down. Never mutates. */
export function sortContacts<T extends ContactLike>(rows: readonly T[]): T[] {
  return [...rows].sort(
    (a, b) =>
      b.date.localeCompare(a.date) ||
      (b.time ?? '').localeCompare(a.time ?? '') ||
      b.createdAt.localeCompare(a.createdAt),
  )
}

/** yyyy-MM, for the month headers a long log grows into. */
export function contactMonth(date: string): string {
  return date.slice(0, 7)
}

/** How many contacts fall in a given yyyy-MM. A count of entries, never of anyone. */
export function contactsInMonth(rows: readonly ContactLike[], month: string): number {
  return rows.filter((r) => contactMonth(r.date) === month).length
}
