/**
 * Child health record structure (CP8).
 *
 * What this module is: a filing cabinet. A dated line saying what was measured,
 * what was given, what was attended. Nothing here interprets a number, and there
 * is deliberately no diagnosis type and no advice string anywhere — a growth
 * figure is reported exactly as the parent typed it, with no percentile, no
 * band, no "normal" and no "should".
 *
 * Every entry is C4 and private by default. Widening one is the owner's own,
 * separate action; this module never decides who can see anything.
 *
 * No copy here: types come back as keys and the component translates them.
 */

export type HealthEntryType = 'tinggi' | 'berat' | 'imunisasi' | 'obat' | 'kunjungan' | 'reaksi'

export const HEALTH_ENTRY_TYPES: readonly HealthEntryType[] = [
  'tinggi',
  'berat',
  'imunisasi',
  'obat',
  'kunjungan',
  'reaksi',
]

/** Units the app fills in, so two parents do not log 12 kg and 12000 g. */
export const ENTRY_UNIT: Record<HealthEntryType, string | undefined> = {
  tinggi: 'cm',
  berat: 'kg',
  imunisasi: undefined,
  obat: undefined,
  kunjungan: undefined,
  reaksi: undefined,
}

export function isMeasurement(type: HealthEntryType): boolean {
  return ENTRY_UNIT[type] !== undefined
}

export interface HealthEntryLike {
  entryType: HealthEntryType
  /** yyyy-MM-dd. */
  date: string
  value?: string
}

/**
 * A number out of a hand-typed field. Accepts the Indonesian decimal comma,
 * because a parent typing "12,4" means 12.4 and a silent NaN would drop the row.
 */
export function parseMeasure(raw: string | undefined): number | undefined {
  const n = Number((raw ?? '').replace(',', '.').trim())
  return Number.isFinite(n) && n > 0 ? n : undefined
}

/** Newest first. Same-day entries keep a stable order by type. */
export function sortEntries<T extends HealthEntryLike>(list: readonly T[]): T[] {
  return [...list].sort((a, b) => b.date.localeCompare(a.date) || a.entryType.localeCompare(b.entryType))
}

export function ofType<T extends HealthEntryLike>(list: readonly T[], type: HealthEntryType): T[] {
  return sortEntries(list).filter((e) => e.entryType === type)
}

/** The most recent entry of each type, for the summary line. */
export function latestByType<T extends HealthEntryLike>(
  list: readonly T[],
): Partial<Record<HealthEntryType, T>> {
  const out: Partial<Record<HealthEntryType, T>> = {}
  for (const e of sortEntries(list)) if (!out[e.entryType]) out[e.entryType] = e
  return out
}

export interface MeasureChange {
  from: number
  to: number
  /** Rounded to one decimal: the input is one decimal, so the difference is too. */
  delta: number
  fromDate: string
  toDate: string
  days: number
  unit: string
}

/**
 * The difference between the two most recent measurements of one type.
 *
 * Arithmetic on the user's own two numbers and nothing else. It carries no
 * judgement, no expected value and no comparison to any population — a parent
 * can read "+0.4 kg over 62 days"; only a clinic can say what that means.
 */
export function measureChange(
  list: readonly HealthEntryLike[],
  type: HealthEntryType,
): MeasureChange | undefined {
  const unit = ENTRY_UNIT[type]
  if (!unit) return undefined
  const rows = ofType(list, type)
    .map((e) => ({ date: e.date, n: parseMeasure(e.value) }))
    .filter((r): r is { date: string; n: number } => r.n !== undefined)
  const [to, from] = rows // sorted newest first
  if (!to || !from) return undefined
  const days = Math.round(
    (Date.parse(`${to.date}T00:00:00Z`) - Date.parse(`${from.date}T00:00:00Z`)) / 86_400_000,
  )
  return {
    from: from.n,
    to: to.n,
    delta: Math.round((to.n - from.n) * 10) / 10,
    fromDate: from.date,
    toDate: to.date,
    days,
    unit,
  }
}
