/**
 * Third-party access (CP15): a grandparent, a nanny, a teacher — scoped to a
 * single child and a single capability.
 *
 * "Scoped to one child and one capability" is the whole design. A grant is not a
 * role with a bundle of permissions; it is exactly one (child, capability) pair.
 * Letting the nanny both see the schedule *and* do pickup for one child is two
 * grants, not one grant with two boxes ticked — so revoking half is always a
 * clean act, and no grant can quietly widen.
 *
 * ponytail: this app has no accounts and no second login (Rp0, offline, single
 * device), so a grant is a *recorded scope*, not an authenticated session. It
 * says what the third party is allowed to be shown; the app enforces it at the
 * point it decides what to render. The documented gap — a real per-person login —
 * belongs to a sync/account layer this build deliberately does not ship.
 *
 * No copy here: role and capability come back as keys the component translates.
 */

export type ThirdPartyRole = 'kakek_nenek' | 'pengasuh' | 'guru' | 'keluarga' | 'lainnya'
export const THIRD_PARTY_ROLES: readonly ThirdPartyRole[] = [
  'kakek_nenek',
  'pengasuh',
  'guru',
  'keluarga',
  'lainnya',
]

/**
 * The closed list of what a single grant can permit. Health is deliberately not
 * here: it is C4, private by default (CP8), and never reachable through a
 * lightweight grant like this one.
 */
export type ThirdPartyCapability =
  | 'lihat_jadwal'
  | 'lihat_serah_terima'
  | 'antar_jemput'
  | 'lihat_kegiatan'
export const THIRD_PARTY_CAPABILITIES: readonly ThirdPartyCapability[] = [
  'lihat_jadwal',
  'lihat_serah_terima',
  'antar_jemput',
  'lihat_kegiatan',
]

export interface GrantLike {
  /** The one child this grant is about. Never a list. */
  childId: string
  /** The one thing it permits. Never a set. */
  capability: ThirdPartyCapability
  /** Revoked grants stay on file (append-only history) but permit nothing. */
  active: boolean
}

/**
 * The scoping check: a grant permits an action only when it is live and the
 * child *and* capability both match exactly. This is the single choke point —
 * every "may this person see X for this child" question routes through it.
 */
export function grantAllows(
  g: GrantLike,
  childId: string,
  capability: ThirdPartyCapability,
): boolean {
  return g.active && g.childId === childId && g.capability === capability
}

/** The live capabilities a set of grants confers for one child. De-duplicated. */
export function capabilitiesFor(
  grants: readonly GrantLike[],
  childId: string,
): ThirdPartyCapability[] {
  const out = new Set<ThirdPartyCapability>()
  for (const g of grants) {
    if (g.active && g.childId === childId) out.add(g.capability)
  }
  return THIRD_PARTY_CAPABILITIES.filter((c) => out.has(c))
}
