/**
 * Export for legal or mediation use (CP16).
 *
 * The one rule: factual records only. No interpretation, no score, no
 * planned-vs-actual "who missed days", no mood, no free-text note that carries an
 * opinion, no health. A mediator or a lawyer gets the dated facts — a handover
 * happened, a cost was agreed, a decision was logged — and draws their own
 * conclusions. This file must never emit anything that could be read back as
 * evidence of a parent's character.
 *
 * What that means concretely, and why each exclusion is here:
 *   - handovers keep date/time/place/who-handed-over and the two tick timestamps,
 *     because a tick is a fact ("this side confirmed on this date"). Mood,
 *     condition, and the free-text notes are dropped — a note reads as an opinion.
 *   - only *agreed* schedule changes appear. A proposed or rejected swap is a
 *     negotiation, not a fact of care, and "rejected" reads as conflict.
 *   - costs and reimbursements keep label/date/amount/status/side; notes dropped.
 *   - decisions keep the agreed summary (it is jointly-owned, append-only) but
 *     not the extra note.
 *   - contacts keep that-it-happened only — CP13 never stored content to leak.
 *   - the planned-vs-actual reconciliation is *never* passed in and never built
 *     here. It is the one figure that could rank a parent, so it stays out.
 *
 * No copy: section headings are message keys, values are raw data (`aku`/`dia`
 * are caregiver labels, not sentences). The component renders and, if asked,
 * downloads the same factual object.
 */

import type { CaregiverKey } from './schedule'

export interface ExportHandover {
  date: string
  time?: string
  place?: string
  from: CaregiverKey
  confirmedByAku?: string
  confirmedByDia?: string
}

export interface ExportSwap {
  date: string
  untilDate?: string
  counterDate?: string
  askedBy?: CaregiverKey
  status: string
}

export interface ExportCost {
  label: string
  date: string
  amount: number
  paidBy?: CaregiverKey
  requestedBy?: CaregiverKey
  status: string
}

export interface ExportDecision {
  date: string
  summary: string
  decidedBy: string
  category: string
}

export interface ExportContact {
  date: string
  time?: string
  channel: string
  initiatedBy?: CaregiverKey
  connected?: boolean
}

export interface ExportCalendar {
  title: string
  date: string
  endDate?: string
  category: string
}

export interface ExportInput {
  handovers?: readonly ExportHandover[]
  /** Every swap; this module keeps only the agreed ones. */
  swaps?: readonly ExportSwap[]
  expenses?: readonly ExportCost[]
  reimbursements?: readonly ExportCost[]
  decisions?: readonly ExportDecision[]
  contacts?: readonly ExportContact[]
  calendar?: readonly ExportCalendar[]
}

export interface ExportDoc {
  /** ISO timestamp the packet was built. A fact about the export, not the family. */
  generatedAt: string
  handovers: ExportHandover[]
  schedule: ExportSwap[]
  expenses: ExportCost[]
  reimbursements: ExportCost[]
  decisions: ExportDecision[]
  contacts: ExportContact[]
  calendar: ExportCalendar[]
  counts: Record<
    'handovers' | 'schedule' | 'expenses' | 'reimbursements' | 'decisions' | 'contacts' | 'calendar',
    number
  >
}

const byDate = <T extends { date: string }>(rows: readonly T[]): T[] =>
  [...rows].sort((a, b) => a.date.localeCompare(b.date))

/** Only agreed changes are facts of care; everything else is negotiation. */
function agreedSwaps(swaps: readonly ExportSwap[]): ExportSwap[] {
  return byDate(swaps.filter((s) => s.status === 'disetujui')).map((s) => ({
    date: s.date,
    ...(s.untilDate ? { untilDate: s.untilDate } : {}),
    ...(s.counterDate ? { counterDate: s.counterDate } : {}),
    ...(s.askedBy ? { askedBy: s.askedBy } : {}),
    status: s.status,
  }))
}

/** Strip a cost row to its facts. `paidBy`/`requestedBy` are preserved as given. */
function costs(rows: readonly ExportCost[]): ExportCost[] {
  return byDate(rows).map((c) => ({
    label: c.label,
    date: c.date,
    amount: Math.round(c.amount),
    ...(c.paidBy ? { paidBy: c.paidBy } : {}),
    ...(c.requestedBy ? { requestedBy: c.requestedBy } : {}),
    status: c.status,
  }))
}

/**
 * Build the factual packet. Every field that survives is a dated fact; every
 * field that could read as an opinion or a verdict is dropped on the way in, not
 * hidden at render time — so there is no path by which interpretation leaks out.
 */
export function buildLegalExport(input: ExportInput, generatedAt: string): ExportDoc {
  const handovers = byDate(input.handovers ?? []).map((h) => ({
    date: h.date,
    ...(h.time ? { time: h.time } : {}),
    ...(h.place ? { place: h.place } : {}),
    from: h.from,
    ...(h.confirmedByAku ? { confirmedByAku: h.confirmedByAku } : {}),
    ...(h.confirmedByDia ? { confirmedByDia: h.confirmedByDia } : {}),
  }))
  const schedule = agreedSwaps(input.swaps ?? [])
  const expenses = costs(input.expenses ?? [])
  const reimbursements = costs(input.reimbursements ?? [])
  const decisions = byDate(input.decisions ?? []).map((d) => ({
    date: d.date,
    summary: d.summary,
    decidedBy: d.decidedBy,
    category: d.category,
  }))
  const contacts = byDate(input.contacts ?? []).map((c) => ({
    date: c.date,
    ...(c.time ? { time: c.time } : {}),
    channel: c.channel,
    ...(c.initiatedBy ? { initiatedBy: c.initiatedBy } : {}),
    ...(typeof c.connected === 'boolean' ? { connected: c.connected } : {}),
  }))
  const calendar = byDate(input.calendar ?? []).map((e) => ({
    title: e.title,
    date: e.date,
    ...(e.endDate ? { endDate: e.endDate } : {}),
    category: e.category,
  }))

  return {
    generatedAt,
    handovers,
    schedule,
    expenses,
    reimbursements,
    decisions,
    contacts,
    calendar,
    counts: {
      handovers: handovers.length,
      schedule: schedule.length,
      expenses: expenses.length,
      reimbursements: reimbursements.length,
      decisions: decisions.length,
      contacts: contacts.length,
      calendar: calendar.length,
    },
  }
}

/** True when the packet carries no records at all — the component warns instead of exporting an empty file. */
export function isEmptyExport(doc: ExportDoc): boolean {
  return Object.values(doc.counts).every((n) => n === 0)
}
