/**
 * School and activity calendar (CP9), shared between households.
 *
 * A dated entry both parents can see: a school day, an exam, a club, a parent
 * meeting, a holiday span. No copy here — the category comes back as a key and
 * the component translates it. Nothing is ever seeded: this app ships no term
 * dates or public-holiday list it cannot cite, so every row is one a parent
 * typed in.
 */

import type { CaregiverKey } from './schedule'

export type CalCategory = 'sekolah' | 'kegiatan' | 'ujian' | 'rapat' | 'libur' | 'lainnya'
export const CAL_CATEGORIES: readonly CalCategory[] = [
  'sekolah',
  'kegiatan',
  'ujian',
  'rapat',
  'libur',
  'lainnya',
]

/** Which side takes the child to it, or both. A label, never a profile id. */
export type CalHousehold = CaregiverKey | 'keduanya'
export const CAL_HOUSEHOLDS: readonly CalHousehold[] = ['aku', 'dia', 'keduanya']

export interface CalLike {
  date: string
  /** Last day of a span (a holiday week, a camp). Absent means a single day. */
  endDate?: string
  /** Local clock time, HH:mm. Absent is honest — "some time that day". */
  time?: string
}

/** The last day an entry still touches. A span runs until its end. */
export function lastDay(e: CalLike): string {
  return e.endDate && e.endDate > e.date ? e.endDate : e.date
}

/** By start day, then clock time, then a stable-ish fallback. Never mutates input. */
export function sortCal<T extends CalLike>(rows: readonly T[]): T[] {
  return [...rows].sort(
    (a, b) => a.date.localeCompare(b.date) || (a.time ?? '').localeCompare(b.time ?? ''),
  )
}

/** Still-running or future entries, soonest first. An event today stays here. */
export function upcomingCal<T extends CalLike>(rows: readonly T[], today: string): T[] {
  return sortCal(rows).filter((r) => lastDay(r) >= today)
}

/** Finished entries, most recent first — the history half of the same list. */
export function pastCal<T extends CalLike>(rows: readonly T[], today: string): T[] {
  return sortCal(rows)
    .filter((r) => lastDay(r) < today)
    .reverse()
}

/** yyyy-MM, for grouping a long list into month sections. */
export function calMonth(date: string): string {
  return date.slice(0, 7)
}

/** Splits a sorted list into `{ month, rows }` blocks, order preserved. */
export function groupByMonth<T extends CalLike>(rows: readonly T[]): { month: string; rows: T[] }[] {
  const out: { month: string; rows: T[] }[] = []
  for (const r of rows) {
    const month = calMonth(r.date)
    const tail = out[out.length - 1]
    if (tail && tail.month === month) tail.rows.push(r)
    else out.push({ month, rows: [r] })
  }
  return out
}
