/**
 * Neutral-language guard (CP14).
 *
 * Any free-text box that one parent writes and the other parent reads passes
 * through here before it is saved. The guard never blocks and never rewrites —
 * censoring somebody's own note would be its own kind of harm. It flags: it spots
 * name-calling, absolute accusations ("you never", "you always"), and direct
 * blame ("because of you"), and hands the component a gentle heads-up so the
 * writer can decide whether to soften it before it lands in the other house.
 *
 * No copy here. Each flag is a message key plus the matched fragment, so the
 * component owns every word the user actually sees.
 *
 * ponytail: a static Indonesian phrase list, not sentiment analysis. It is meant
 * to catch the obvious and prompt a second thought, not to police tone — no model
 * ships in an offline, Rp0 app, and a heuristic that oversteps would be worse
 * than one that misses. Extend the list, don't reach for an API.
 */

export type NeutralCategory = 'insult' | 'absolute' | 'blame'

export interface NeutralFlag {
  category: NeutralCategory
  /** The exact fragment that tripped it, so the component can quote it back. */
  term: string
  /** Message key for the guidance shown against this category. */
  key: string
}

/**
 * Phrases, lowercased. Multi-word entries match as a contiguous phrase; the whole
 * table is matched on word boundaries so `malas` does not fire inside `semalas`.
 * Indonesian first, with the handful of English equivalents people code-switch to.
 */
const TABLE: { category: NeutralCategory; terms: readonly string[] }[] = [
  {
    category: 'insult',
    terms: [
      'bodoh', 'tolol', 'goblok', 'dungu', 'pemalas', 'malas', 'egois',
      'pembohong', 'penipu', 'jahat', 'brengsek', 'bangsat', 'sok',
      'tidak becus', 'nggak becus', 'gagal', 'payah', 'menyebalkan',
      'stupid', 'lazy', 'liar', 'selfish', 'useless',
    ],
  },
  {
    category: 'absolute',
    terms: [
      'kamu selalu', 'kamu tidak pernah', 'kamu nggak pernah', 'kamu gak pernah',
      'selalu saja', 'tidak pernah mau', 'nggak pernah mau', 'dasar',
      'you always', 'you never',
    ],
  },
  {
    category: 'blame',
    terms: [
      'gara-gara kamu', 'gara2 kamu', 'karena kamu', 'salah kamu', 'salahmu',
      'gara-gara dia', 'karena dia', 'salah dia', 'ulah kamu', 'ulahmu',
      'your fault', 'because of you',
    ],
  },
]

const keyFor: Record<NeutralCategory, string> = {
  insult: 'coparenting.neutral.insult',
  absolute: 'coparenting.neutral.absolute',
  blame: 'coparenting.neutral.blame',
}

function escape(s: string): string {
  return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
}

/**
 * Every flag raised by `text`, in the order the terms appear, de-duplicated by
 * matched fragment. Empty array means nothing tripped — the writer is clear.
 */
export function checkNeutral(text: string): NeutralFlag[] {
  const hay = ` ${text.toLowerCase()} `
  const hits: { at: number; flag: NeutralFlag }[] = []
  const seen = new Set<string>()
  for (const { category, terms } of TABLE) {
    for (const term of terms) {
      // \b sits at a word boundary; for phrases with spaces or hyphens the outer
      // boundaries are what matter, and JS treats the hyphen edge as a boundary.
      const re = new RegExp(`(?<![a-z])${escape(term)}(?![a-z])`, 'i')
      const m = re.exec(hay)
      if (m && !seen.has(term)) {
        seen.add(term)
        hits.push({ at: m.index, flag: { category, term, key: keyFor[category] } })
      }
    }
  }
  return hits.sort((a, b) => a.at - b.at).map((h) => h.flag)
}

/** True when the text raises no flag. The write is never gated on this. */
export function isNeutral(text: string): boolean {
  return checkNeutral(text).length === 0
}
