/**
 * Ngasuh bareng — co-parenting (handover-first).
 *
 * Two design decisions run through the whole screen:
 *
 * 1. **Solo Mode is the base case, not a fallback.** Caregivers are labels, not
 *    profiles, so nothing here needs the other parent to install anything, agree
 *    to anything, or exist in the database. A swap "answer" is something the
 *    owner records after a phone call; the app never claims to have sent it.
 * 2. **Nothing describes the other parent.** No pattern detection, no
 *    reliability figure, no "best parent". Planned-vs-actual reports days on
 *    both sides and stops there.
 *
 * Records live in the `family` store — see `types.ts` for why.
 */

const STORE = 'family' as const
const PREVIEW_DAYS = 14
/** Range the planned-vs-actual table looks back over. Long enough to be useful,
 *  short enough that nobody reads it as a permanent record of a person. */
const REVIEW_DAYS = 28

type Tab = 'overview' | 'child' | 'handover' | 'rota' | 'cal' | 'money' | 'topic' | 'contact' | 'decision' | 'access' | 'export'
const TABS: readonly Tab[] = ['overview', 'child', 'handover', 'rota', 'cal', 'money', 'topic', 'contact', 'decision', 'access', 'export']

export default function Coparenting() {
  const { t, locale: uiLocale } = useI18n()
  // `dwi` is a display mode, not a language — formatters and data tables
  // take the real one.
  const locale = baseLocale(uiLocale)
  const { profile, partner } = useSession()
  const me = profile?.id
  const [tab, setTab] = useState<Tab>('handover')

  const rows = useOwned<CoparentRecord>(STORE, me)
  const setup =
    useLiveQuery(async () => ((await db.settings.get(SETUP_KEY))?.value as CoparentSetup) ?? DEFAULT_SETUP, []) ??
    DEFAULT_SETUP

  const of = useMemo(
    () =>
      <K extends CoparentKind>(kind: K): Cp<K>[] =>
        (rows ?? []).filter((r): r is Cp<K> => r.kind === kind),
    [rows],
  )

  if (!profile || !me) return null

  const names: Record<CaregiverKey, string> = {
    aku: t('coparenting.who.aku'),
    dia: setup.otherParentLabel.trim() || partner?.displayName || t('coparenting.who.dia'),
  }

  // CP5/CP6. One object decides how much of the other parent is on screen, so
  // no component has to re-derive it from `partner` and get it half-right.
  const mode = modeOf(!!partner, setup.parallel)

  const kids = of('child')
  const rotas = of('cp_rota')
  const activeRota = rotas.find((r) => r.active)
  const swaps = of('cp_swap')

  return (
    <div className="stack">
      <h1>{t('coparenting.title')}</h1>
      <p className="card__hint">{t('coparenting.subtitle')}</p>

      {!partner && (
        <div className="banner">
          <Icon name="info" size={18} />
          <span className="stack stack--tight">
            <strong>{t('coparenting.solo.title')}</strong>
            <span>{t('coparenting.solo.body')}</span>
          </span>
        </div>
      )}

      {mode.parallel && (
        <div className="banner">
          <Icon name="shield" size={18} />
          <span className="stack stack--tight">
            <strong>{t('coparenting.parallel.title')}</strong>
            <span>{t('coparenting.parallel.body')}</span>
          </span>
        </div>
      )}

      <Setup setup={setup} />

      {/* `.row` wraps, so five labels still fit at 320 px without a side-scroll. */}
      <div className="row" role="group" aria-label={t('coparenting.tabGroup')}>
        {TABS.map((k) => (
          <button
            key={k}
            type="button"
            aria-pressed={tab === k}
            className={tab === k ? 'btn btn--sm' : 'btn btn--soft btn--sm'}
            onClick={() => setTab(k)}
          >
            {t(`coparenting.tab.${k}` as const)}
          </button>
        ))}
      </div>

      {tab === 'overview' && <Overview t={t} locale={locale} rows={rows ?? []} />}

      {tab === 'child' && (
        <Children
          me={me}
          t={t}
          locale={locale}
          names={names}
          mode={mode}
          kids={kids}
          health={of('cp_health')}
          entries={of('cp_health_entry')}
          changes={of('cp_child_change')}
        />
      )}

      {tab === 'handover' && (
        <Handovers me={me} t={t} locale={locale} names={names} kids={kids} cards={of('cp_handover')} />
      )}

      {tab === 'rota' && (
        <Schedule
          me={me}
          t={t}
          locale={locale}
          names={names}
          mode={mode}
          rotas={rotas}
          activeRota={activeRota}
          swaps={swaps}
          actuals={of('cp_actual')}
        />
      )}

      {tab === 'cal' && (
        <SchoolCalendar me={me} t={t} locale={locale} names={names} kids={kids} events={of('cp_cal')} />
      )}

      {tab === 'money' && (
        <div className="stack">
          <Expenses
            me={me}
            t={t}
            locale={locale}
            names={names}
            mode={mode}
            kids={kids}
            expenses={of('cp_expense')}
          />
          <Reimbursements
            me={me}
            t={t}
            locale={locale}
            names={names}
            mode={mode}
            expenses={of('cp_expense')}
            requests={of('cp_reimburse')}
          />
        </div>
      )}

      {tab === 'topic' && <Topics me={me} t={t} locale={locale} mode={mode} topics={of('cp_topic')} />}

      {tab === 'contact' && (
        <ContactLog me={me} t={t} locale={locale} names={names} kids={kids} contacts={of('cp_contact')} />
      )}

      {tab === 'decision' && (
        <Decisions me={me} t={t} locale={locale} names={names} kids={kids} decisions={of('cp_decision')} />
      )}

      {tab === 'access' && (
        <ThirdPartyAccess me={me} t={t} locale={locale} names={names} kids={kids} grants={of('cp_thirdparty')} />
      )}

      {tab === 'export' && (
        <LegalExport
          me={me}
          t={t}
          locale={locale}
          names={names}
          handovers={of('cp_handover')}
          swaps={swaps}
          expenses={of('cp_expense')}
          reimbursements={of('cp_reimburse')}
          decisions={of('cp_decision')}
          contacts={of('cp_contact')}
          calendar={of('cp_cal')}
        />
      )}

      <p className="disclaimer">{t('coparenting.disclaimer')}</p>
    </div>
  )
}

// ---------------------------------------------------------------------------
// Setup
// ---------------------------------------------------------------------------

function Setup({ setup }: { setup: CoparentSetup }) {
  const t = useT()
  const save = (next: Partial<CoparentSetup>) =>
    db.settings.put({ key: SETUP_KEY, value: { ...setup, ...next } })

  return (
    <Card title={t('coparenting.setup.title')} icon="settings">
      <Field label={t('coparenting.setup.otherParent')} hint={t('coparenting.setup.otherParentHint')}>
        {(p) => (
          <input
            {...p}
            value={setup.otherParentLabel}
            placeholder={t('coparenting.setup.otherParentPlaceholder')}
            onChange={(e) => save({ otherParentLabel: e.target.value })}
          />
        )}
      </Field>
      <div className="row row--between">
        <span className="stack stack--tight grow">
          <strong style={{ fontSize: 14 }}>{t('coparenting.setup.parallel')}</strong>
          <span className="card__hint">{t('coparenting.setup.parallelHint')}</span>
        </span>
        <button
          type="button"
          aria-pressed={setup.parallel}
          className={setup.parallel ? 'btn btn--sm' : 'btn btn--soft btn--sm'}
          onClick={() => save({ parallel: !setup.parallel })}
        >
          {t(setup.parallel ? 'coparenting.setup.parallelOn' : 'coparenting.setup.parallelOff')}
        </button>
      </div>
    </Card>
  )
}

