function ChildSheet({
  open,
  onClose,
  me,
  t,
  mode,
  existing,
}: {
  open: boolean
  onClose: () => void
  me: string
  t: TFunction
  mode: Mode
  existing: Cp<'child'> | null
}) {
  // Mounted only while open, so every open starts from the record's own values
  // rather than whatever the last edit left behind. No effect needed.
  return (
    <Sheet open={open} onClose={onClose} title={t(existing ? 'coparenting.child.edit' : 'coparenting.child.add')}>
      {open && (
        <ChildForm key={existing?.id ?? 'new'} onClose={onClose} me={me} t={t} mode={mode} existing={existing} />
      )}
    </Sheet>
  )
}

function ChildForm({
  onClose,
  me,
  t,
  mode,
  existing,
}: {
  onClose: () => void
  me: string
  t: TFunction
  mode: Mode
  existing: Cp<'child'> | null
}) {
  const [name, setName] = useState(existing?.name ?? '')
  const [birthDate, setBirthDate] = useState(existing?.birthDate ?? todayISO())
  const [school, setSchool] = useState(existing?.school ?? '')
  const [clothingSize, setClothingSize] = useState(existing?.clothingSize ?? '')
  const [shoeSize, setShoeSize] = useState(existing?.shoeSize ?? '')
  const [dates, setDates] = useState<KeyDate[]>(existing?.dates ?? [])
  const [emergency, setEmergency] = useState(existing?.emergencyContact ?? '')
  const [pickup, setPickup] = useState(existing?.pickupAllowed ?? '')
  const [note, setNote] = useState(existing?.note ?? '')

  async function save() {
    if (!name.trim()) return
    const keyDates = sortKeyDates(dates)
    const body = {
      name: name.trim(),
      birthDate,
      school: school.trim() || undefined,
      clothingSize: clothingSize.trim() || undefined,
      shoeSize: shoeSize.trim() || undefined,
      dates: keyDates.length > 0 ? keyDates : undefined,
      emergencyContact: emergency.trim() || undefined,
      pickupAllowed: lines(pickup).join('\n') || undefined,
      note: note.trim() || undefined,
    }

    // CP7. The profile is jointly owned, so a change nobody can see is a change
    // nobody agreed to. `diffChild` returns an empty list when the form was only
    // opened and closed, which is why saving twice writes no history at all.
    let childId: string
    if (existing) {
      await patch(STORE, existing.id, body)
      childId = existing.id
    } else {
      // Logistics are the household's shared business (C2); the medical parts of
      // a child live in `cp_health` precisely so they can stay private.
      const env = newEnvelope(me, 'C2_shared_ops')
      await db.family.add({ ...env, kind: 'child', ...body } as never)
      childId = env.id
    }
    for (const c of diffChild(existing, body)) {
      await db.family.add({
        ...newEnvelope(me, 'C2_shared_ops'),
        kind: 'cp_child_change',
        childId,
        field: c.field,
        ...(c.from ? { from: c.from } : {}),
        ...(c.to ? { to: c.to } : {}),
      } as never)
    }
    onClose()
  }

  return (
    <div className="stack">
      <Field label={t('coparenting.child.name')}>
        {(p) => <input {...p} value={name} onChange={(e) => setName(e.target.value)} />}
      </Field>
      <Field label={t('coparenting.child.birthDate')}>
        {(p) => <input {...p} type="date" value={birthDate} onChange={(e) => setBirthDate(e.target.value)} />}
      </Field>
      <Field label={t('coparenting.child.school')} hint={t('common.optional')}>
        {(p) => <input {...p} value={school} onChange={(e) => setSchool(e.target.value)} />}
      </Field>
      <Field label={t('coparenting.child.clothingSize')} hint={t('coparenting.child.sizeHint')}>
        {(p) => <input {...p} value={clothingSize} onChange={(e) => setClothingSize(e.target.value)} />}
      </Field>
      <Field label={t('coparenting.child.shoeSize')} hint={t('coparenting.child.sizeHint')}>
        {(p) => <input {...p} value={shoeSize} onChange={(e) => setShoeSize(e.target.value)} />}
      </Field>
      <KeyDatesEditor value={dates} onChange={setDates} t={t} />
      <Field label={t('coparenting.child.emergency')} hint={t('coparenting.child.emergencyHint')}>
        {(p) => <input {...p} value={emergency} onChange={(e) => setEmergency(e.target.value)} />}
      </Field>
      <Field label={t('coparenting.child.pickup')} hint={t('coparenting.child.pickupHint')}>
        {(p) => <textarea {...p} rows={3} value={pickup} onChange={(e) => setPickup(e.target.value)} />}
      </Field>
      {allowsFreeText('childNote', mode) && (
        <Field label={t('coparenting.child.note')} hint={t('common.optional')}>
          {(p) => <textarea {...p} rows={2} value={note} onChange={(e) => setNote(e.target.value)} />}
        </Field>
      )}
      <div className="row">
        <button className="btn grow" onClick={save} disabled={!name.trim()}>{t('common.save')}</button>
        <button className="btn btn--ghost" onClick={onClose}>{t('common.cancel')}</button>
      </div>
    </div>
  )
}

