// ---------------------------------------------------------------------------
// Handover cards — the centre of the module
// ---------------------------------------------------------------------------

function Handovers({
  me,
  t,
  locale,
  names,
  kids,
  cards,
}: Common & {
  names: Record<CaregiverKey, string>
  kids: Cp<'child'>[]
  cards: Cp<'cp_handover'>[]
}) {
  const [open, setOpen] = useState(false)
  const [copiedId, setCopiedId] = useState<string | null>(null)
  const sorted = sortHandovers(cards)
  const waiting = countUnconfirmed(cards)

  async function copy(card: Cp<'cp_handover'>) {
    const text = handoverText(card, t, locale, names, kids)
    try {
      await navigator.clipboard.writeText(text)
      setCopiedId(card.id)
    } catch {
      // Clipboard needs a secure context and a user gesture; if the browser says
      // no we say nothing rather than claiming a copy that did not happen.
      setCopiedId(null)
    }
  }

  return (
    <>
      <Card
        title={t('coparenting.ho.title')}
        icon="family"
        hint={t('coparenting.ho.hint')}
        action={
          <button className="btn btn--sm" onClick={() => setOpen(true)}>
            <Icon name="plus" size={16} /> {t('coparenting.ho.new')}
          </button>
        }
      >
        {/* A plain count of cards, never of people: no side is named here, and
            nothing on this screen adds up to a figure about a parent. */}
        {waiting > 0 && (
          <div className="row">
            <span className="chip">{t('coparenting.ho.unconfirmed', { n: waiting })}</span>
          </div>
        )}

        {sorted.length === 0 ? (
          <EmptyState icon="family" title={t('coparenting.ho.none')} hint={t('coparenting.ho.noneHint')} />
        ) : (
          <div className="stack">
            {sorted.map((c) => {
              const child = kids.find((x) => x.id === c.childId)
              const rows: [MessageKey, string | undefined][] = [
                ['coparenting.ho.condition', c.condition],
                ['coparenting.ho.mood', c.mood ? t(`coparenting.ho.mood.${c.mood}` as const) : undefined],
                ['coparenting.ho.sleep', c.sleep],
                ['coparenting.ho.lastMeal', c.lastMeal],
                ['coparenting.ho.lastMedicine', c.lastMedicine],
                ['coparenting.ho.homework', c.homework],
                [
                  'coparenting.ho.pocketMoney',
                  c.pocketMoney !== undefined ? formatRupiah(c.pocketMoney, locale) : undefined,
                ],
              ]
              const filled = rows.filter(([, v]) => v)
              return (
                <section key={c.id} className="card card--flat stack stack--tight">
                  <div className="row row--between">
                    <span className="stack stack--tight grow">
                      <strong>
                        {whenLabel(c.date, t, locale)}
                        {normalTime(c.time) ? ` · ${normalTime(c.time)}` : ''}
                        {child ? ` · ${child.name}` : ''}
                      </strong>
                      <span className="card__hint">
                        {t('coparenting.ho.handedBy', { name: names[c.from] })}
                        {c.place ? ` · ${c.place}` : ''}
                      </span>
                    </span>
                    <VisibilityBadge visibility={c.visibility} />
                    <DeleteButton id={c.id} me={me} t={t} />
                  </div>

                  {filled.length === 0 && lines(c.broughtItems).length === 0 && lines(c.returnItems).length === 0 ? (
                    <p className="card__hint">{t('coparenting.ho.nothingFilled')}</p>
                  ) : (
                    <ul className="list">
                      {filled.map(([k, v]) => (
                        <li key={k} className="list__item">
                          <span className="grow stack stack--tight">
                            <strong style={{ fontSize: 13 }}>{t(k)}</strong>
                            <span className="card__hint">{v}</span>
                          </span>
                        </li>
                      ))}
                    </ul>
                  )}

                  {lines(c.broughtItems).length > 0 && (
                    <ItemList title={t('coparenting.ho.brought')} items={lines(c.broughtItems)} icon="groceries" />
                  )}
                  {lines(c.returnItems).length > 0 && (
                    <ItemList title={t('coparenting.ho.return')} items={lines(c.returnItems)} icon="restore" />
                  )}

                  <ConfirmRow card={c} t={t} locale={locale} names={names} />

                  <div className="row">
                    <button className="btn btn--soft btn--sm" onClick={() => copy(c)}>
                      <Icon name="export" size={16} /> {copiedId === c.id ? t('coparenting.ho.copied') : t('coparenting.ho.copy')}
                    </button>
                  </div>
                  <p className="card__hint">{t('coparenting.ho.copyHint')}</p>
                </section>
              )
            })}
          </div>
        )}
      </Card>

      <Sheet open={open} onClose={() => setOpen(false)} title={t('coparenting.ho.new')}>
        {open && (
          <HandoverForm onClose={() => setOpen(false)} me={me} t={t} names={names} kids={kids} />
        )}
      </Sheet>
    </>
  )
}

/**
 * Both-sides confirmation of one handover card (CP2).
 *
 * The unconfirmed state is on screen, unmissable, and blameless: the sentence
 * names whoever *did* tick, the hint says out loud that a missing tick is not a
 * failure, and there is no timer, no overdue colour, and no reminder aimed at
 * the other parent. A tick can also be undone — in Solo Mode the owner is the
 * one pressing both buttons, and a mis-tap must not become a permanent claim.
 */
function ConfirmRow({
  card,
  t,
  locale,
  names,
}: {
  card: Cp<'cp_handover'>
  t: TFunction
  locale: 'id' | 'en'
  names: Record<CaregiverKey, string>
}) {
  const state = confirmState(card)
  // The one side that ticked, when exactly one has: the visible sentence names
  // them, so it never has to name the side that has not.
  const ticked = state.confirmedBy[0]

  return (
    <div className="stack stack--tight">
      <div className="row row--between">
        <strong style={{ fontSize: 13 }}>{t('coparenting.ho.confirm.title')}</strong>
        <span className={state.state === 'both' ? 'chip chip--mint' : 'chip'}>
          {state.state === 'partial' && ticked
            ? t('coparenting.ho.confirm.partial', { name: names[ticked] })
            : t(state.key as MessageKey)}
        </span>
      </div>

      {state.state !== 'both' && <p className="card__hint">{t('coparenting.ho.confirm.hint')}</p>}

      <div className="row">
        {CAREGIVERS.map((who) => {
          const at = confirmedAt(card, who)
          return (
            <button
              key={who}
              type="button"
              aria-pressed={at !== undefined}
              className={at ? 'btn btn--sm' : 'btn btn--soft btn--sm'}
              onClick={() => patch(STORE, card.id, toggleConfirm(card, who, new Date().toISOString()))}
            >
              {at && <Icon name="check" size={16} />}
              {t(at ? 'coparenting.ho.confirm.untick' : 'coparenting.ho.confirm.tick', { name: names[who] })}
            </button>
          )
        })}
      </div>

      {state.confirmedBy.map((who) => (
        <span key={who} className="card__hint">
          {t('coparenting.ho.confirm.at', {
            name: names[who],
            date: fmtDate((confirmedAt(card, who) as string).slice(0, 10), 'd MMM', locale),
          })}
        </span>
      ))}
    </div>
  )
}

function ItemList({ title, items, icon }: { title: string; items: string[]; icon: 'groceries' | 'restore' }) {
  return (
    <>
      <strong style={{ fontSize: 13 }}>{title}</strong>
      <ul className="list">
        {items.map((i) => (
          <li key={i} className="list__item">
            <Icon name={icon} size={16} />
            <span className="grow">{i}</span>
          </li>
        ))}
      </ul>
    </>
  )
}

/** Plain text for the clipboard. Nothing leaves the device — the user pastes it. */
function handoverText(
  c: Cp<'cp_handover'>,
  t: TFunction,
  locale: 'id' | 'en',
  names: Record<CaregiverKey, string>,
  kids: Cp<'child'>[],
): string {
  const child = kids.find((x) => x.id === c.childId)
  const time = normalTime(c.time)
  const out: string[] = [
    `${t('coparenting.ho.title')} — ${fmtDate(c.date, 'd MMM yyyy', locale)}${time ? ` ${time}` : ''}${child ? ` · ${child.name}` : ''}`,
    t('coparenting.ho.handedBy', { name: names[c.from] }),
  ]
  const add = (key: MessageKey, value: string | undefined) => {
    if (value) out.push(`${t(key)}: ${value}`)
  }
  add('coparenting.ho.place', c.place)
  add('coparenting.ho.condition', c.condition)
  add('coparenting.ho.mood', c.mood ? t(`coparenting.ho.mood.${c.mood}` as const) : undefined)
  add('coparenting.ho.sleep', c.sleep)
  add('coparenting.ho.lastMeal', c.lastMeal)
  add('coparenting.ho.lastMedicine', c.lastMedicine)
  add('coparenting.ho.homework', c.homework)
  add('coparenting.ho.brought', lines(c.broughtItems).join(', ') || undefined)
  add('coparenting.ho.return', lines(c.returnItems).join(', ') || undefined)
  add('coparenting.ho.pocketMoney', c.pocketMoney !== undefined ? formatRupiah(c.pocketMoney, locale) : undefined)
  return out.join('\n')
}

function HandoverForm({
  onClose,
  me,
  t,
  names,
  kids,
}: {
  onClose: () => void
  me: string
  t: TFunction
  names: Record<CaregiverKey, string>
  kids: Cp<'child'>[]
}) {
  const [date, setDate] = useState(todayISO())
  const [time, setTime] = useState('')
  const [place, setPlace] = useState('')
  const [childId, setChildId] = useState(kids[0]?.id ?? '')
  const [from, setFrom] = useState<CaregiverKey>('aku')
  const [condition, setCondition] = useState('')
  const [mood, setMood] = useState<ChildMood | ''>('')
  const [sleep, setSleep] = useState('')
  const [lastMeal, setLastMeal] = useState('')
  const [lastMedicine, setLastMedicine] = useState('')
  const [homework, setHomework] = useState('')
  const [brought, setBrought] = useState('')
  const [ret, setRet] = useState('')
  const [pocket, setPocket] = useState('')

  async function save() {
    await db.family.add({
      ...newEnvelope(me, 'C2_shared_ops'),
      kind: 'cp_handover',
      date,
      // Normalised on the way in, so a stray value can never reorder the list.
      ...(normalTime(time) ? { time: normalTime(time) } : {}),
      ...(place.trim() ? { place: place.trim() } : {}),
      ...(childId ? { childId } : {}),
      from,
      ...(condition.trim() ? { condition: condition.trim() } : {}),
      ...(mood ? { mood } : {}),
      ...(sleep.trim() ? { sleep: sleep.trim() } : {}),
      ...(lastMeal.trim() ? { lastMeal: lastMeal.trim() } : {}),
      ...(lastMedicine.trim() ? { lastMedicine: lastMedicine.trim() } : {}),
      ...(homework.trim() ? { homework: homework.trim() } : {}),
      ...(lines(brought).length ? { broughtItems: lines(brought).join('\n') } : {}),
      ...(lines(ret).length ? { returnItems: lines(ret).join('\n') } : {}),
      ...(pocket && Number.isFinite(Number(pocket)) ? { pocketMoney: Math.round(Number(pocket)) } : {}),
    } as never)
    onClose()
  }

  return (
    <div className="stack">
      <Field label={t('common.date')}>
        {(p) => <input {...p} type="date" value={date} onChange={(e) => setDate(e.target.value)} />}
      </Field>
      {/* Native pickers on purpose: the platform already knows the locale, the
          12/24-hour habit, and how to be accessible. */}
      <Field label={t('coparenting.ho.time')} hint={t('coparenting.ho.timeHint')}>
        {(p) => <input {...p} type="time" value={time} onChange={(e) => setTime(e.target.value)} />}
      </Field>
      <Field label={t('coparenting.ho.place')} hint={t('coparenting.ho.placeHint')}>
        {(p) => <input {...p} value={place} onChange={(e) => setPlace(e.target.value)} />}
      </Field>

      {kids.length === 0 ? (
        <p className="card__hint">{t('coparenting.needChild')}</p>
      ) : (
        <Field label={t('coparenting.ho.child')}>
          {(p) => (
            <select {...p} value={childId} onChange={(e) => setChildId(e.target.value)}>
              {kids.map((c) => (
                <option key={c.id} value={c.id}>{c.name}</option>
              ))}
            </select>
          )}
        </Field>
      )}

      <CaregiverPicker value={from} onChange={setFrom} names={names} legend={t('coparenting.ho.from')} />

      <Field label={t('coparenting.ho.condition')} hint={t('coparenting.ho.conditionHint')}>
        {(p) => <textarea {...p} rows={2} value={condition} onChange={(e) => setCondition(e.target.value)} />}
      </Field>

      <fieldset style={{ border: 0, padding: 0, margin: 0 }} className="stack stack--tight">
        <legend style={{ fontSize: 13, fontWeight: 700, padding: 0 }}>{t('coparenting.ho.mood')}</legend>
        <div className="row">
          {CHILD_MOODS.map((m) => (
            <button
              key={m}
              type="button"
              aria-pressed={mood === m}
              className={mood === m ? 'btn btn--sm' : 'btn btn--soft btn--sm'}
              onClick={() => setMood(mood === m ? '' : m)}
            >
              {t(`coparenting.ho.mood.${m}` as const)}
            </button>
          ))}
        </div>
      </fieldset>

      <Field label={t('coparenting.ho.sleep')} hint={t('coparenting.ho.sleepHint')}>
        {(p) => <input {...p} value={sleep} onChange={(e) => setSleep(e.target.value)} />}
      </Field>
      <Field label={t('coparenting.ho.lastMeal')} hint={t('common.optional')}>
        {(p) => <input {...p} value={lastMeal} onChange={(e) => setLastMeal(e.target.value)} />}
      </Field>
      <Field label={t('coparenting.ho.lastMedicine')} hint={t('coparenting.ho.medicineHint')}>
        {(p) => <input {...p} value={lastMedicine} onChange={(e) => setLastMedicine(e.target.value)} />}
      </Field>
      <Field label={t('coparenting.ho.homework')} hint={t('common.optional')}>
        {(p) => <textarea {...p} rows={2} value={homework} onChange={(e) => setHomework(e.target.value)} />}
      </Field>
      <Field label={t('coparenting.ho.brought')} hint={t('coparenting.ho.broughtHint')}>
        {(p) => <textarea {...p} rows={3} value={brought} onChange={(e) => setBrought(e.target.value)} />}
      </Field>
      <Field label={t('coparenting.ho.return')} hint={t('coparenting.ho.returnHint')}>
        {(p) => <textarea {...p} rows={3} value={ret} onChange={(e) => setRet(e.target.value)} />}
      </Field>
      <Field label={t('coparenting.ho.pocketMoney')} hint={t('common.optional')}>
        {(p) => (
          <input {...p} type="number" inputMode="numeric" min={0} value={pocket} onChange={(e) => setPocket(e.target.value)} />
        )}
      </Field>

      <div className="row">
        <button className="btn grow" onClick={save}>{t('common.save')}</button>
        <button className="btn btn--ghost" onClick={onClose}>{t('common.cancel')}</button>
      </div>
    </div>
  )
}

// ---------------------------------------------------------------------------
// Schedule: rota, swaps, planned vs actual
// ---------------------------------------------------------------------------

function Schedule({
  me,
  t,
  locale,
  names,
  mode,
  rotas,
  activeRota,
  swaps,
  actuals,
}: Common & {
  names: Record<CaregiverKey, string>
  mode: Mode
  rotas: Cp<'cp_rota'>[]
  activeRota: Cp<'cp_rota'> | undefined
  swaps: Cp<'cp_swap'>[]
  actuals: Cp<'cp_actual'>[]
}) {
  const [rotaSheet, setRotaSheet] = useState(false)
  const [swapDate, setSwapDate] = useState<string | null>(null)
  const [logDate, setLogDate] = useState<string | null>(null)
  const today = todayISO()

  const rota: Rota | null = activeRota ? { anchorDate: activeRota.anchorDate, days: activeRota.days } : null
  const preview = rota ? expand(rota, swaps, today, PREVIEW_DAYS) : []
  const reviewFrom = addDays(today, -REVIEW_DAYS)
  const review = rota ? reconcile(expand(rota, swaps, reviewFrom, REVIEW_DAYS), actuals) : null

  return (
    <>
      <Card
        title={t('coparenting.rota.title')}
        icon="calendar"
        hint={t('coparenting.rota.hint')}
        action={
          <button className="btn btn--sm" onClick={() => setRotaSheet(true)}>
            <Icon name="plus" size={16} /> {t('coparenting.rota.new')}
          </button>
        }
      >
        {rotas.length === 0 ? (
          <EmptyState icon="calendar" title={t('coparenting.rota.none')} hint={t('coparenting.rota.noneHint')} />
        ) : (
          <ul className="list">
            {rotas.map((r) => (
              <li key={r.id} className="list__item">
                <Icon name="calendar" size={18} />
                <span className="grow stack stack--tight">
                  <strong style={{ fontSize: 14 }}>{r.label}</strong>
                  <span className="card__hint">
                    {t('coparenting.rota.customHint', { days: r.days.length })}
                  </span>
                </span>
                {r.active ? (
                  <span className="chip chip--primary">{t('coparenting.rota.active')}</span>
                ) : (
                  <button
                    className="btn btn--soft btn--sm"
                    onClick={async () => {
                      // Exactly one rota is live; anything else makes "who has
                      // them tomorrow" unanswerable.
                      for (const other of rotas) if (other.active) await patch(STORE, other.id, { active: false })
                      await patch(STORE, r.id, { active: true })
                    }}
                  >
                    {t('coparenting.rota.activate')}
                  </button>
                )}
                <DeleteButton id={r.id} me={me} t={t} />
              </li>
            ))}
          </ul>
        )}
      </Card>

      {rota && (
        <Card title={t('coparenting.rota.preview')} icon="calendar">
          {preview.length === 0 ? (
            <p className="card__hint">{t('coparenting.rota.emptyPattern')}</p>
          ) : (
            <ul className="list">
              {preview.map((d) => (
                <li key={d.date} className="list__item">
                  <span className="grow stack stack--tight">
                    <strong style={{ fontSize: 14 }}>{whenLabel(d.date, t, locale)}</strong>
                    {d.swapped && <span className="card__hint">{t('coparenting.rota.swapped')}</span>}
                  </span>
                  <Who who={d.effective} names={names} />
                  <button className="btn btn--ghost btn--sm" onClick={() => setSwapDate(d.date)}>
                    {t('coparenting.rota.askSwap')}
                  </button>
                </li>
              ))}
            </ul>
          )}
        </Card>
      )}

      <Card title={t('coparenting.swap.title')} icon="repair" hint={t('coparenting.swap.hint')}>
        {swaps.length === 0 ? (
          <EmptyState icon="repair" title={t('coparenting.swap.none')} />
        ) : (
          <div className="stack">
            {[...swaps]
              .sort((a, b) => b.date.localeCompare(a.date))
              .map((s) => (
                <section key={s.id} className="card card--flat stack stack--tight">
                  <div className="row row--between">
                    <span className="stack stack--tight grow">
                      <strong style={{ fontSize: 14 }}>
                        {isRange(s)
                          ? t('coparenting.swap.range', {
                              from: fmtDate(s.date, 'd MMM', locale),
                              to: fmtDate(s.untilDate ?? s.date, 'd MMM', locale),
                            })
                          : whenLabel(s.date, t, locale)}
                      </strong>
                      <span className="card__hint">
                        {t(`coparenting.swap.reason.${s.reason}` as const)} · {t('coparenting.swap.askedBy')}: {names[s.askedBy]}
                      </span>
                      {isRange(s) && (
                        <span className="card__hint">
                          {t('coparenting.swap.exception')} · {t('coparenting.swap.rangeHolder', { name: names[s.askedBy] })}
                        </span>
                      )}
                      {s.counterDate && !isRange(s) && (
                        <span className="card__hint">
                          {t('coparenting.swap.tradeWith', { date: fmtDate(s.counterDate, 'd MMM', locale) })}
                        </span>
                      )}
                      {s.note && allowsFreeText('swapNote', mode) && <span className="card__hint">“{s.note}”</span>}
                      {s.answeredAt && (
                        <span className="card__hint">
                          {t('coparenting.swap.answeredOn', { date: fmtDate(s.answeredAt, 'd MMM', locale) })}
                        </span>
                      )}
                    </span>
                    <span className="chip">{t(statusKey('swap', s.status, mode) as MessageKey)}</span>
                    <DeleteButton id={s.id} me={me} t={t} />
                  </div>

                  {s.status !== 'disetujui' && s.status !== 'ditolak' && (
                    <SwapAnswer swap={s} t={t} rota={rota} names={names} />
                  )}
                </section>
              ))}
          </div>
        )}
        <p className="card__hint">{t('coparenting.swap.recordHint')}</p>
      </Card>

      <Card
        title={t('coparenting.actual.title')}
        icon="checkin"
        hint={t('coparenting.actual.hint')}
        action={
          <button className="btn btn--sm" onClick={() => setLogDate(today)} disabled={!rota}>
            <Icon name="plus" size={16} /> {t('coparenting.actual.log')}
          </button>
        }
      >
        {!rota ? (
          <EmptyState icon="checkin" title={t('coparenting.needRota')} />
        ) : !review || review.compared === 0 ? (
          <EmptyState icon="checkin" title={t('coparenting.actual.none')} />
        ) : (
          <>
            <p className="card__hint">
              {t('coparenting.actual.range', { from: fmtDate(reviewFrom, 'd MMM', locale), days: REVIEW_DAYS })}
            </p>
            <div className="row">
              <span className="chip">{t('coparenting.actual.compared', { days: review.compared })}</span>
              <span className="chip">{t('coparenting.actual.unlogged', { days: review.unlogged })}</span>
              <span className="chip">{t('coparenting.actual.different', { days: review.different.length })}</span>
            </div>
            <div className="table-scroll">
              <table>
                <thead>
                  <tr>
                    <th style={th}>{t('coparenting.actual.person')}</th>
                    <th style={th}>{t('coparenting.actual.planned')}</th>
                    <th style={th}>{t('coparenting.actual.real')}</th>
                    <th style={th}>{t('coparenting.actual.hoursCol')}</th>
                  </tr>
                </thead>
                <tbody>
                  {(['aku', 'dia'] as const).map((k) => (
                    <tr key={k}>
                      <td style={td}>{names[k]}</td>
                      <td style={td}>{t('coparenting.actual.days', { n: review.days[k].planned })}</td>
                      <td style={td}>{t('coparenting.actual.days', { n: review.days[k].actual })}</td>
                      <td style={td}>{review.hours[k] || '—'}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </>
        )}
        {/* Outside the branches on purpose: the framing has to be on screen
            whenever the card is, not only once there is data to misread. */}
        <p className="disclaimer">{t('coparenting.actual.notAScore')}</p>
      </Card>

      <Sheet open={rotaSheet} onClose={() => setRotaSheet(false)} title={t('coparenting.rota.new')}>
        {rotaSheet && <RotaForm onClose={() => setRotaSheet(false)} me={me} t={t} names={names} />}
      </Sheet>

      <Sheet open={swapDate !== null} onClose={() => setSwapDate(null)} title={t('coparenting.swap.new')}>
        {swapDate && (
          <SwapForm
            key={swapDate}
            date={swapDate}
            onClose={() => setSwapDate(null)}
            me={me}
            t={t}
            names={names}
            mode={mode}
          />
        )}
      </Sheet>

      <Sheet open={logDate !== null} onClose={() => setLogDate(null)} title={t('coparenting.actual.log')}>
        {logDate && rota && (
          <ActualForm
            key={logDate}
            initialDate={logDate}
            rota={rota}
            swaps={swaps}
            onClose={() => setLogDate(null)}
            me={me}
            t={t}
            names={names}
            mode={mode}
          />
        )}
      </Sheet>
    </>
  )
}

const th: React.CSSProperties = {
  textAlign: 'left',
  padding: '5px 4px',
  borderBottom: '1px solid var(--border)',
  fontWeight: 800,
  fontSize: 12,
}
const td: React.CSSProperties = {
  textAlign: 'left',
  padding: '5px 4px',
  borderBottom: '1px solid var(--border)',
  fontWeight: 400,
}

/** Accept / decline / counter. In Solo Mode this is the owner writing down what
 *  was agreed on the phone — the app never pretends to have delivered anything. */
function SwapAnswer({
  swap,
  t,
  rota,
  names,
}: {
  swap: Cp<'cp_swap'>
  t: TFunction
  rota: Rota | null
  names: Record<CaregiverKey, string>
}) {
  const [counter, setCounter] = useState('')
  const answeredAt = () => todayISO()

  return (
    <div className="stack stack--tight">
      <div className="row">
        <button
          className="btn btn--sm"
          onClick={() => patch(STORE, swap.id, { status: 'disetujui', answeredAt: answeredAt() })}
        >
          <Icon name="check" size={16} /> {t('coparenting.swap.accept')}
        </button>
        <button
          className="btn btn--soft btn--sm"
          onClick={() => patch(STORE, swap.id, { status: 'ditolak', answeredAt: answeredAt() })}
        >
          {t('coparenting.swap.decline')}
        </button>
      </div>
      {/* A multi-day exception has no single day to trade back, so the counter
          controls are hidden rather than offered and then ignored. */}
      {isRange(swap) ? (
        <p className="card__hint">{t('coparenting.swap.exceptionHint')}</p>
      ) : (
        <>
          <Field label={t('coparenting.swap.counterDate')} hint={t('coparenting.swap.counterHint')}>
            {(p) => <input {...p} type="date" value={counter} onChange={(e) => setCounter(e.target.value)} />}
          </Field>
          {counter && rota && (
            <p className="card__hint">
              {t('coparenting.actual.planned')}: {names[effectiveFor(rota, [], counter) ?? 'aku']}
            </p>
          )}
          <div className="row">
            <button
              className="btn btn--soft btn--sm"
              disabled={!counter || counter === swap.date}
              onClick={() => patch(STORE, swap.id, { status: 'ditawar', counterDate: counter, answeredAt: answeredAt() })}
            >
              {t('coparenting.swap.counter')}
            </button>
            {swap.status === 'ditawar' && swap.counterDate && (
              <button
                className="btn btn--sm"
                onClick={() => patch(STORE, swap.id, { status: 'disetujui', answeredAt: answeredAt() })}
              >
                <Icon name="check" size={16} /> {t('coparenting.swap.accept')}
              </button>
            )}
          </div>
        </>
      )}
    </div>
  )
}

function RotaForm({
  onClose,
  me,
  t,
  names,
}: {
  onClose: () => void
  me: string
  t: TFunction
  names: Record<CaregiverKey, string>
}) {
  const [label, setLabel] = useState('')
  const [anchorDate, setAnchorDate] = useState(todayISO())
  const [days, setDays] = useState<CaregiverKey[]>([])

  const toggle = (i: number) =>
    setDays((d) => d.map((v, j) => (j === i ? (v === 'aku' ? 'dia' : 'aku') : v)))

  async function save() {
    if (!label.trim() || days.length === 0) return
    await db.family.add({
      ...newEnvelope(me, 'C2_shared_ops'),
      kind: 'cp_rota',
      label: label.trim(),
      anchorDate,
      days,
      // A brand-new rota goes live only if there is nothing to displace; the
      // list has an explicit "use this one" so switching is never a side effect.
      active: false,
    } as never)
    onClose()
  }

  return (
    <div className="stack">
      <Field label={t('coparenting.rota.label')}>
        {(p) => (
          <input
            {...p}
            value={label}
            placeholder={t('coparenting.rota.labelPlaceholder')}
            onChange={(e) => setLabel(e.target.value)}
          />
        )}
      </Field>
      <Field label={t('coparenting.rota.anchor')} hint={t('coparenting.rota.anchorHint')}>
        {(p) => <input {...p} type="date" value={anchorDate} onChange={(e) => setAnchorDate(e.target.value)} />}
      </Field>

      <strong style={{ fontSize: 13 }}>{t('coparenting.rota.preset')}</strong>
      <div className="row">
        {ROTA_PRESETS.map((p) => (
          <button
            key={p.key}
            type="button"
            className="btn btn--soft btn--sm"
            onClick={() => setDays([...p.days])}
          >
            {t(p.key as MessageKey)}
          </button>
        ))}
      </div>

      <strong style={{ fontSize: 13 }}>{t('coparenting.rota.custom')}</strong>
      <p className="card__hint">{t('coparenting.rota.customHint', { days: days.length })}</p>
      <div className="row">
        {days.map((d, i) => (
          <button
            key={i}
            type="button"
            className={d === 'aku' ? 'btn btn--sm' : 'btn btn--soft btn--sm'}
            // Capped so a long "other parent" label cannot push the sheet wider
            // than 320 px. The name still reads; it just wraps inside the button.
            style={{ maxWidth: '100%' }}
            aria-label={`${t('coparenting.rota.dayN', { n: i + 1 })}: ${names[d]}`}
            onClick={() => toggle(i)}
          >
            {i + 1}. {names[d]}
          </button>
        ))}
      </div>
      <div className="row">
        <button type="button" className="btn btn--soft btn--sm" onClick={() => setDays((d) => [...d, 'aku'])}>
          <Icon name="plus" size={16} /> {t('coparenting.rota.addDay')}
        </button>
        <button
          type="button"
          className="btn btn--ghost btn--sm"
          disabled={days.length === 0}
          onClick={() => setDays((d) => d.slice(0, -1))}
        >
          {t('coparenting.rota.removeDay')}
        </button>
      </div>

      <div className="row">
        <button className="btn grow" onClick={save} disabled={!label.trim() || days.length === 0}>
          {t('common.save')}
        </button>
        <button className="btn btn--ghost" onClick={onClose}>{t('common.cancel')}</button>
      </div>
    </div>
  )
}

function SwapForm({
  date,
  onClose,
  me,
  t,
  names,
  mode,
}: {
  date: string
  onClose: () => void
  me: string
  t: TFunction
  names: Record<CaregiverKey, string>
  mode: Mode
}) {
  const [when, setWhen] = useState(date)
  const [until, setUntil] = useState('')
  const [askedBy, setAskedBy] = useState<CaregiverKey>('aku')
  const [reason, setReason] = useState<SwapReason>('kerjaan')
  const [note, setNote] = useState('')
  const range = until > when

  async function save() {
    await db.family.add({
      ...newEnvelope(me, 'C2_shared_ops'),
      kind: 'cp_swap',
      date: when,
      // Only stored when it actually spans days: a stray end date equal to or
      // before the start would silently mean nothing.
      ...(range ? { untilDate: until } : {}),
      askedBy,
      reason,
      // Parallel parenting means no free text crosses between households.
      ...(allowsFreeText('swapNote', mode) && note.trim() ? { note: note.trim() } : {}),
      // Solo Mode: there is nobody to answer, so this is recorded as a change to
      // the plan rather than parked on a reply that is never coming.
      status: newSwapStatus(mode),
    } as never)
    onClose()
  }

  return (
    <div className="stack">
      <Field label={t('coparenting.swap.date')}>
        {(p) => <input {...p} type="date" value={when} onChange={(e) => setWhen(e.target.value)} />}
      </Field>
      <Field label={t('coparenting.swap.until')} hint={t('coparenting.swap.untilHint')}>
        {(p) => <input {...p} type="date" min={when} value={until} onChange={(e) => setUntil(e.target.value)} />}
      </Field>
      <CaregiverPicker value={askedBy} onChange={setAskedBy} names={names} legend={t('coparenting.swap.askedBy')} />
      {range && (
        <p className="card__hint">
          {t('coparenting.swap.exception')} · {t('coparenting.swap.rangeHolder', { name: names[askedBy] })}
          {' '}
          {t('coparenting.swap.exceptionHint')}
        </p>
      )}
      <Field label={t('coparenting.swap.reason')}>
        {(p) => (
          <select {...p} value={reason} onChange={(e) => setReason(e.target.value as SwapReason)}>
            {SWAP_REASONS.map((r) => (
              <option key={r} value={r}>{t(`coparenting.swap.reason.${r}` as const)}</option>
            ))}
          </select>
        )}
      </Field>
      {allowsFreeText('swapNote', mode) ? (
        <Field label={t('coparenting.swap.note')} hint={t('coparenting.swap.noteHint')}>
          {(p) => <textarea {...p} rows={2} value={note} onChange={(e) => setNote(e.target.value)} />}
        </Field>
      ) : (
        <p className="card__hint">{t('coparenting.swap.parallelNote')}</p>
      )}
      {/* Said before the save, not after: alone, this is a note to yourself. */}
      {mode.solo && <p className="card__hint">{t('coparenting.swap.soloHint')}</p>}
      <div className="row">
        <button className="btn grow" onClick={save}>{t('common.save')}</button>
        <button className="btn btn--ghost" onClick={onClose}>{t('common.cancel')}</button>
      </div>
    </div>
  )
}

function ActualForm({
  initialDate,
  rota,
  swaps,
  onClose,
  me,
  t,
  names,
  mode,
}: {
  initialDate: string
  rota: Rota
  swaps: Cp<'cp_swap'>[]
  onClose: () => void
  me: string
  t: TFunction
  names: Record<CaregiverKey, string>
  mode: Mode
}) {
  const [date, setDate] = useState(initialDate)
  // Pre-filled with the plan: the common case is "it went as agreed", and
  // making that one tap keeps the log honest instead of sparse.
  const [caregiver, setCaregiver] = useState<CaregiverKey>(effectiveFor(rota, swaps, initialDate) ?? 'aku')
  const [hours, setHours] = useState('')
  const [note, setNote] = useState('')

  async function save() {
    const n = Number(hours)
    await db.family.add({
      ...newEnvelope(me, 'C2_shared_ops'),
      kind: 'cp_actual',
      date,
      caregiver,
      ...(hours && Number.isFinite(n) && n > 0 ? { hours: n } : {}),
      ...(note.trim() ? { note: note.trim() } : {}),
    } as never)
    onClose()
  }

  return (
    <div className="stack">
      <Field label={t('common.date')}>
        {(p) => (
          <input
            {...p}
            type="date"
            value={date}
            onChange={(e) => {
              setDate(e.target.value)
              setCaregiver(effectiveFor(rota, swaps, e.target.value) ?? 'aku')
            }}
          />
        )}
      </Field>
      <CaregiverPicker value={caregiver} onChange={setCaregiver} names={names} legend={t('coparenting.actual.who')} />
      <Field label={t('coparenting.actual.hours')} hint={t('coparenting.actual.hoursHint')}>
        {(p) => (
          <input {...p} type="number" inputMode="numeric" min={0} max={24} value={hours} onChange={(e) => setHours(e.target.value)} />
        )}
      </Field>
      {allowsFreeText('actualNote', mode) && (
        <Field label={t('coparenting.actual.note')} hint={t('common.optional')}>
          {(p) => <textarea {...p} rows={2} value={note} onChange={(e) => setNote(e.target.value)} />}
        </Field>
      )}
      <p className="disclaimer">{t('coparenting.actual.notAScore')}</p>
      <div className="row">
        <button className="btn grow" onClick={save}>{t('common.save')}</button>
        <button className="btn btn--ghost" onClick={onClose}>{t('common.cancel')}</button>
      </div>
    </div>
  )
}

// ---------------------------------------------------------------------------
// Expenses
// ---------------------------------------------------------------------------

const EXPENSE_STATUSES: readonly ExpenseStatus[] = ['diajukan', 'disetujui', 'dibayar', 'disengketakan']

function Expenses({
  me,
  t,
  locale,
  names,
  mode,
  kids,
  expenses,
}: Common & {
  mode: Mode
  names: Record<CaregiverKey, string>
  kids: Cp<'child'>[]
  expenses: Cp<'cp_expense'>[]
}) {
  const [open, setOpen] = useState(false)
  const l = ledger(expenses)
  const sorted = [...expenses].sort((a, b) => b.date.localeCompare(a.date))

  return (
    <>
      <Card
        title={t('coparenting.exp.title')}
        icon="money"
        hint={t('coparenting.exp.hint')}
        action={
          <button className="btn btn--sm" onClick={() => setOpen(true)}>
            <Icon name="plus" size={16} /> {t('coparenting.exp.new')}
          </button>
        }
      >
        <div className="row">
          <span className="chip chip--mint">
            {t('coparenting.exp.owedToMe')}: {formatRupiah(l.owedToMe, locale)}
          </span>
          <span className="chip chip--blue">
            {t('coparenting.exp.owedByMe')}: {formatRupiah(l.owedByMe, locale)}
          </span>
          <span className="chip chip--yellow">
            {t('coparenting.exp.proposed')}: {formatRupiah(l.proposed, locale)}
          </span>
          <span className="chip chip--lavender">
            {t('coparenting.exp.disputed')}: {formatRupiah(l.disputed, locale)}
          </span>
        </div>
        <p className="disclaimer">{t('coparenting.exp.ledgerHint')}</p>

        {sorted.length === 0 ? (
          <EmptyState icon="money" title={t('coparenting.exp.none')} hint={t('coparenting.exp.noneHint')} />
        ) : (
          <div className="stack">
            {sorted.map((e) => {
              const split = splitAmount(e.amount, e.myShare)
              const child = kids.find((c) => c.id === e.childId)
              return (
                <section key={e.id} className="card card--flat stack stack--tight">
                  <div className="row row--between">
                    <span className="stack stack--tight grow">
                      <strong style={{ fontSize: 14 }}>{e.label}</strong>
                      <span className="card__hint">
                        {whenLabel(e.date, t, locale)} · {formatRupiah(e.amount, locale)}
                        {child ? ` · ${child.name}` : ''}
                      </span>
                      <span className="card__hint">
                        {t('coparenting.exp.split', {
                          mine: formatRupiah(split.mine, locale),
                          other: names.dia,
                          theirs: formatRupiah(split.theirs, locale),
                        })}
                      </span>
                      <span className="card__hint">
                        {t('coparenting.exp.paidBy')}: {names[e.paidBy]}
                      </span>
                      {e.proof && (
                        <span className="card__hint">
                          {t('coparenting.exp.proof')}:{' '}
                          {t('coparenting.exp.proofChosen', {
                            name: e.proof.fileName,
                            size: Math.max(1, Math.round(e.proof.sizeBytes / 1024)),
                          })}
                        </span>
                      )}
                      {e.note && allowsFreeText('expenseNote', mode) && (
                        <span className="card__hint">{e.note}</span>
                      )}
                    </span>
                    <DeleteButton id={e.id} me={me} t={t} />
                  </div>
                  <fieldset style={{ border: 0, padding: 0, margin: 0 }} className="stack stack--tight">
                    <legend style={{ fontSize: 12, fontWeight: 700, padding: 0 }}>
                      {t('coparenting.exp.setStatus')}
                    </legend>
                    <div className="row">
                      {EXPENSE_STATUSES.map((s) => (
                        <button
                          key={s}
                          type="button"
                          aria-pressed={e.status === s}
                          className={e.status === s ? 'btn btn--sm' : 'btn btn--soft btn--sm'}
                          onClick={() => patch(STORE, e.id, { status: s })}
                        >
                          {t(`coparenting.exp.status.${s}` as const)}
                        </button>
                      ))}
                    </div>
                  </fieldset>
                </section>
              )
            })}
          </div>
        )}
      </Card>

      <Sheet open={open} onClose={() => setOpen(false)} title={t('coparenting.exp.new')}>
        {open && (
          <ExpenseForm onClose={() => setOpen(false)} me={me} t={t} names={names} mode={mode} kids={kids} />
        )}
      </Sheet>
    </>
  )
}

function ExpenseForm({
  onClose,
  me,
  t,
  names,
  mode,
  kids,
}: {
  onClose: () => void
  me: string
  t: TFunction
  names: Record<CaregiverKey, string>
  mode: Mode
  kids: Cp<'child'>[]
}) {
  const { locale } = useI18n()
  const [label, setLabel] = useState('')
  const [amount, setAmount] = useState('')
  const [date, setDate] = useState(todayISO())
  const [paidBy, setPaidBy] = useState<CaregiverKey>('aku')
  const [percent, setPercent] = useState(50)
  const [childId, setChildId] = useState('')
  const [note, setNote] = useState('')
  const [proof, setProof] = useState<ProofMeta | null>(null)

  const n = Math.round(Number(amount))
  const valid = label.trim().length > 0 && Number.isFinite(n) && n > 0

  async function save() {
    if (!valid) return
    await db.family.add({
      ...newEnvelope(me, 'C2_shared_ops'),
      kind: 'cp_expense',
      label: label.trim(),
      date,
      amount: n,
      myShare: percent / 100,
      paidBy,
      ...(childId ? { childId } : {}),
      status: 'diajukan',
      ...(proof ? { proof } : {}),
      ...(note.trim() ? { note: note.trim() } : {}),
    } as never)
    onClose()
  }

  return (
    <div className="stack">
      <Field label={t('coparenting.exp.label')}>
        {(p) => <input {...p} value={label} onChange={(e) => setLabel(e.target.value)} />}
      </Field>
      <Field label={t('common.rupiah')}>
        {(p) => (
          <input {...p} type="number" inputMode="numeric" min={0} value={amount} onChange={(e) => setAmount(e.target.value)} />
        )}
      </Field>
      <Field label={t('common.date')}>
        {(p) => <input {...p} type="date" value={date} onChange={(e) => setDate(e.target.value)} />}
      </Field>
      <CaregiverPicker value={paidBy} onChange={setPaidBy} names={names} legend={t('coparenting.exp.paidBy')} />

      <Field label={t('coparenting.exp.share')} hint={t('coparenting.exp.shareHint', { percent })}>
        {(p) => (
          <input
            {...p}
            type="range"
            min={0}
            max={100}
            step={5}
            value={percent}
            onChange={(e) => setPercent(Number(e.target.value))}
          />
        )}
      </Field>
      {valid && (
        <p className="card__hint">
          {t('coparenting.exp.split', {
            mine: formatRupiah(splitAmount(n, percent / 100).mine, locale),
            other: names.dia,
            theirs: formatRupiah(splitAmount(n, percent / 100).theirs, locale),
          })}
        </p>
      )}

      {kids.length > 0 && (
        <Field label={t('coparenting.ho.child')} hint={t('common.optional')}>
          {(p) => (
            <select {...p} value={childId} onChange={(e) => setChildId(e.target.value)}>
              <option value="">—</option>
              {kids.map((c) => (
                <option key={c.id} value={c.id}>{c.name}</option>
              ))}
            </select>
          )}
        </Field>
      )}

      <Field label={t('coparenting.exp.proof')} hint={t('coparenting.exp.proofHint')}>
        {(p) => (
          <input
            {...p}
            type="file"
            accept="image/*,application/pdf"
            onChange={(e) => {
              const f = e.target.files?.[0]
              if (f) {
                setProof({
                  fileName: f.name,
                  sizeBytes: f.size,
                  mimeType: f.type,
                  fileDate: new Date(f.lastModified).toISOString(),
                })
              }
              // The blob is dropped here on purpose. TemuDua stores no
              // attachments — a receipt with a name on it is somebody's data.
              e.target.value = ''
            }}
          />
        )}
      </Field>
      {proof && (
        <div className="row">
          <span className="chip">
            {t('coparenting.exp.proofChosen', {
              name: proof.fileName,
              size: Math.max(1, Math.round(proof.sizeBytes / 1024)),
            })}
          </span>
          <button className="btn btn--ghost btn--sm" onClick={() => setProof(null)}>
            {t('coparenting.exp.proofClear')}
          </button>
        </div>
      )}

      {allowsFreeText('expenseNote', mode) && (
        <>
          <Field label={t('coparenting.actual.note')} hint={t('common.optional')}>
            {(p) => <textarea {...p} rows={2} value={note} onChange={(e) => setNote(e.target.value)} />}
          </Field>
          <NeutralHint text={note} t={t} />
        </>
      )}

      <div className="row">
        <button className="btn grow" onClick={save} disabled={!valid}>{t('common.save')}</button>
        <button className="btn btn--ghost" onClick={onClose}>{t('common.cancel')}</button>
      </div>
    </div>
  )
}

// ---------------------------------------------------------------------------
// Structured topic requests (parallel parenting's only channel)
// ---------------------------------------------------------------------------
/**
 * Matters needing an answer.
 *
 * Outside parallel mode this is a short free-text question and a free-text
 * answer. Inside it (CP6) both halves are closed lists: you *pick* a request and
 * the other side picks one of three answers. That is the whole channel — there
 * is nowhere in this module to type a sentence at the other adult, which is the
 * point of parallel parenting.
 */
function Topics({ me, t, locale, mode, topics }: Common & { mode: Mode; topics: Cp<'cp_topic'>[] }) {
  const [open, setOpen] = useState(false)
  const [answering, setAnswering] = useState<Cp<'cp_topic'> | null>(null)
  const sorted = [...topics].sort((a, b) => b.createdAt.localeCompare(a.createdAt))

  return (
    <>
      <Card
        title={t('coparenting.topic.title')}
        icon="consent"
        hint={t('coparenting.topic.hint')}
        action={
          <button className="btn btn--sm" onClick={() => setOpen(true)}>
            <Icon name="plus" size={16} /> {t('coparenting.topic.new')}
          </button>
        }
      >
        {mode.parallel && <p className="card__hint">{t('coparenting.topic.parallelHint')}</p>}
        {/* Alone, an open matter is a to-do, not a message somebody is ignoring. */}
        {mode.solo && <p className="card__hint">{t('coparenting.topic.soloHint')}</p>}

        {sorted.length === 0 ? (
          <EmptyState icon="consent" title={t('coparenting.topic.none')} hint={t('coparenting.topic.noneHint')} />
        ) : (
          <div className="stack">
            {sorted.map((tp) => (
              <section key={tp.id} className="card card--flat stack stack--tight">
                <div className="row row--between">
                  <span className="stack stack--tight grow">
                    <strong style={{ fontSize: 14 }}>
                      {tp.subject || (tp.ask ? t(`coparenting.topic.ask.${tp.ask}` as const) : '')}
                    </strong>
                    <span className="card__hint">{t(`coparenting.topic.cat.${tp.category}` as const)}</span>
                    {tp.ask && tp.subject && <span>{t(`coparenting.topic.ask.${tp.ask}` as const)}</span>}
                    {tp.askAmount !== undefined && (
                      <span className="card__hint">
                        {t('coparenting.topic.askAmount')}: {formatRupiah(tp.askAmount, locale)}
                      </span>
                    )}
                    {tp.question && allowsFreeText('topicText', mode) && <span>{tp.question}</span>}
                    {tp.neededBy && (
                      <span className="card__hint">
                        {t('coparenting.topic.neededBy')}: {fmtDate(tp.neededBy, 'd MMM yyyy', locale)}
                      </span>
                    )}
                    {tp.answerChoice && (
                      <span className="card__hint">
                        {t('coparenting.topic.answer')}: {t(`coparenting.topic.answer.${tp.answerChoice}` as const)}
                      </span>
                    )}
                    {tp.answer && allowsFreeText('topicText', mode) && (
                      <span className="card__hint">
                        {t('coparenting.topic.answer')}: {tp.answer}
                      </span>
                    )}
                  </span>
                  <span className="chip">{t(statusKey('topic', tp.status, mode) as MessageKey)}</span>
                  <DeleteButton id={tp.id} me={me} t={t} />
                </div>
                {tp.status !== 'ditutup' && (
                  <div className="row">
                    <button className="btn btn--soft btn--sm" onClick={() => setAnswering(tp)}>
                      {t('coparenting.topic.recordAnswer')}
                    </button>
                    <button className="btn btn--ghost btn--sm" onClick={() => patch(STORE, tp.id, { status: 'ditutup' })}>
                      {t('coparenting.topic.close')}
                    </button>
                  </div>
                )}
              </section>
            ))}
          </div>
        )}
      </Card>

      <Sheet open={open} onClose={() => setOpen(false)} title={t('coparenting.topic.new')}>
        {open && <TopicForm onClose={() => setOpen(false)} me={me} t={t} mode={mode} />}
      </Sheet>

      <Sheet open={answering !== null} onClose={() => setAnswering(null)} title={t('coparenting.topic.recordAnswer')}>
        {answering && (
          <AnswerForm key={answering.id} topic={answering} onClose={() => setAnswering(null)} t={t} mode={mode} />
        )}
      </Sheet>
    </>
  )
}

function TopicForm({ onClose, me, t, mode }: { onClose: () => void; me: string; t: TFunction; mode: Mode }) {
  const structured = structuredTopicOnly(mode)
  const [category, setCategory] = useState<TopicCategory>('jadwal')
  const [subject, setSubject] = useState('')
  const [question, setQuestion] = useState('')
  const [ask, setAsk] = useState<TopicAsk>('tukar_jadwal')
  const [amount, setAmount] = useState('')
  const [neededBy, setNeededBy] = useState('')

  const amountN = Math.round(Number(amount))
  const wantsAmount = structured && ask === 'biaya_tambahan'
  const valid = structured
    ? !wantsAmount || (Number.isFinite(amountN) && amountN > 0)
    : subject.trim().length > 0 && question.trim().length > 0

  async function save() {
    if (!valid) return
    await db.family.add({
      ...newEnvelope(me, 'C2_shared_ops'),
      kind: 'cp_topic',
      category,
      // Parallel mode stores the picked request and nothing typed. The free-text
      // pair is simply absent, so there is no box for it to reappear from later.
      ...(structured
        ? { ask, ...(wantsAmount ? { askAmount: amountN } : {}) }
        : { subject: subject.trim(), question: question.trim() }),
      ...(neededBy ? { neededBy } : {}),
      status: 'diajukan',
    } as never)
    onClose()
  }

  return (
    <div className="stack">
      {structured && <p className="card__hint">{t('coparenting.topic.parallelHint')}</p>}
      <Field label={t('coparenting.topic.category')}>
        {(p) => (
          <select {...p} value={category} onChange={(e) => setCategory(e.target.value as TopicCategory)}>
            {TOPIC_CATEGORIES.map((c) => (
              <option key={c} value={c}>{t(`coparenting.topic.cat.${c}` as const)}</option>
            ))}
          </select>
        )}
      </Field>

      {structured ? (
        <>
          <Field label={t('coparenting.topic.ask')} hint={t('coparenting.topic.askHint')}>
            {(p) => (
              <select {...p} value={ask} onChange={(e) => setAsk(e.target.value as TopicAsk)}>
                {TOPIC_ASKS.map((a) => (
                  <option key={a} value={a}>{t(`coparenting.topic.ask.${a}` as const)}</option>
                ))}
              </select>
            )}
          </Field>
          {wantsAmount && (
            <Field label={t('coparenting.topic.askAmount')}>
              {(p) => (
                <input {...p} inputMode="numeric" value={amount} onChange={(e) => setAmount(e.target.value)} />
              )}
            </Field>
          )}
        </>
      ) : (
        <>
          <Field label={t('coparenting.topic.subject')}>
            {(p) => <input {...p} value={subject} onChange={(e) => setSubject(e.target.value)} />}
          </Field>
          <Field label={t('coparenting.topic.question')} hint={t('coparenting.topic.questionHint')}>
            {(p) => <textarea {...p} rows={3} value={question} onChange={(e) => setQuestion(e.target.value)} />}
          </Field>
          <NeutralHint text={`${subject} ${question}`} t={t} />
        </>
      )}

      <Field label={t('coparenting.topic.neededBy')} hint={t('common.optional')}>
        {(p) => <input {...p} type="date" value={neededBy} onChange={(e) => setNeededBy(e.target.value)} />}
      </Field>
      <div className="row">
        <button className="btn grow" onClick={save} disabled={!valid}>{t('common.save')}</button>
        <button className="btn btn--ghost" onClick={onClose}>{t('common.cancel')}</button>
      </div>
    </div>
  )
}

function AnswerForm({
  topic,
  onClose,
  t,
  mode,
}: {
  topic: Cp<'cp_topic'>
  onClose: () => void
  t: TFunction
  mode: Mode
}) {
  const [answer, setAnswer] = useState(topic.answer ?? '')
  // A matter raised as a structured request is answered as one, whatever the
  // mode is now: switching parallel mode off must not reopen a text box on a
  // record that never had one.
  const structured = structuredTopicOnly(mode) || topic.ask !== undefined

  async function pick(choice: TopicAnswerChoice) {
    await patch(STORE, topic.id, { answerChoice: choice, status: 'dijawab' })
    onClose()
  }

  async function save() {
    if (!answer.trim()) return
    await patch(STORE, topic.id, { answer: answer.trim(), status: 'dijawab' })
    onClose()
  }

  if (structured) {
    return (
      <div className="stack">
        {topic.ask && <p className="card__hint">{t(`coparenting.topic.ask.${topic.ask}` as const)}</p>}
        <strong style={{ fontSize: 13 }}>{t('coparenting.topic.answerChoice')}</strong>
        <div className="row">
          {TOPIC_ANSWER_CHOICES.map((c) => (
            <button
              key={c}
              type="button"
              aria-pressed={topic.answerChoice === c}
              className={topic.answerChoice === c ? 'btn btn--sm' : 'btn btn--soft btn--sm'}
              onClick={() => pick(c)}
            >
              {t(`coparenting.topic.answer.${c}` as const)}
            </button>
          ))}
        </div>
        <div className="row">
          <button className="btn btn--ghost" onClick={onClose}>{t('common.cancel')}</button>
        </div>
      </div>
    )
  }

  return (
    <div className="stack">
      <p className="card__hint">{topic.question}</p>
      <Field label={t('coparenting.topic.answer')}>
        {(p) => <textarea {...p} rows={3} value={answer} onChange={(e) => setAnswer(e.target.value)} />}
      </Field>
      <NeutralHint text={answer} t={t} />
      <div className="row">
        <button className="btn grow" onClick={save} disabled={!answer.trim()}>{t('common.save')}</button>
        <button className="btn btn--ghost" onClick={onClose}>{t('common.cancel')}</button>
      </div>
    </div>
  )
}

// ---------------------------------------------------------------------------
// School & activity calendar (CP9)
// ---------------------------------------------------------------------------
/**
 * A dated agenda both households read from. Every row is typed by a parent — the
 * app seeds no term dates or holidays it cannot cite. `place` is free text, never
 * a lookup: this module does no location of any kind.
 */

/** aku/dia show the caregiver's name; 'keduanya' is a plain "both" label. */
function householdLabel(h: CalHousehold, names: Record<CaregiverKey, string>, t: TFunction): string {
  return h === 'keduanya' ? t('coparenting.cal.both') : names[h]
}

function SchoolCalendar({
  me,
  t,
  locale,
  names,
  kids,
  events,
}: Common & {
  names: Record<CaregiverKey, string>
  kids: Cp<'child'>[]
  events: Cp<'cp_cal'>[]
}) {
  const [open, setOpen] = useState(false)
  const today = todayISO()
  const upcoming = groupByMonth(upcomingCal(events, today))
  const past = pastCal(events, today)

  const row = (e: Cp<'cp_cal'>) => {
    const child = kids.find((c) => c.id === e.childId)
    const span = lastDay(e) !== e.date
    return (
      <section key={e.id} className="card card--flat stack stack--tight">
        <div className="row row--between">
          <span className="stack stack--tight grow">
            <strong style={{ fontSize: 14 }}>{e.title}</strong>
            <span className="card__hint">
              {span
                ? t('coparenting.cal.span', {
                    from: fmtDate(e.date, 'd MMM', locale),
                    to: fmtDate(lastDay(e), 'd MMM yyyy', locale),
                  })
                : whenLabel(e.date, t, locale)}
              {e.time ? ` · ${e.time}` : ''}
              {` · ${t(`coparenting.cal.cat.${e.category}` as const)}`}
            </span>
            {e.place && <span className="card__hint">{e.place}</span>}
            <span className="row">
              <span className={e.household === 'dia' ? 'chip chip--blue' : 'chip chip--mint'}>
                {householdLabel(e.household, names, t)}
              </span>
              {child && <span className="chip">{child.name}</span>}
            </span>
            {e.note && <span className="card__hint">{e.note}</span>}
          </span>
          <DeleteButton id={e.id} me={me} t={t} />
        </div>
      </section>
    )
  }

  return (
    <>
      <Card
        title={t('coparenting.cal.title')}
        icon="calendar"
        hint={t('coparenting.cal.hint')}
        action={
          <button className="btn btn--sm" onClick={() => setOpen(true)}>
            <Icon name="plus" size={16} /> {t('coparenting.cal.new')}
          </button>
        }
      >
        {events.length === 0 ? (
          <EmptyState icon="calendar" title={t('coparenting.cal.none')} hint={t('coparenting.cal.noneHint')} />
        ) : (
          <div className="stack">
            {upcoming.length > 0 && (
              <div className="stack stack--tight">
                <strong style={{ fontSize: 13 }}>{t('coparenting.cal.upcoming')}</strong>
                {upcoming.map((block) => (
                  <div key={block.month} className="stack stack--tight">
                    <span className="card__hint">{fmtDate(`${block.month}-01`, 'MMMM yyyy', locale)}</span>
                    {block.rows.map(row)}
                  </div>
                ))}
              </div>
            )}
            {past.length > 0 && (
              <div className="stack stack--tight">
                <strong style={{ fontSize: 13 }}>{t('coparenting.cal.past')}</strong>
                {past.map(row)}
              </div>
            )}
          </div>
        )}
      </Card>

      <Sheet open={open} onClose={() => setOpen(false)} title={t('coparenting.cal.new')}>
        {open && <CalForm onClose={() => setOpen(false)} me={me} t={t} names={names} kids={kids} />}
      </Sheet>
    </>
  )
}

function CalForm({
  onClose,
  me,
  t,
  names,
  kids,
}: {
  onClose: () => void
  me: string
  t: TFunction
  names: Record<CaregiverKey, string>
  kids: Cp<'child'>[]
}) {
  const [title, setTitle] = useState('')
  const [category, setCategory] = useState<CalCategory>('sekolah')
  const [date, setDate] = useState(todayISO())
  const [endDate, setEndDate] = useState('')
  const [time, setTime] = useState('')
  const [place, setPlace] = useState('')
  const [household, setHousehold] = useState<CalHousehold>('keduanya')
  const [childId, setChildId] = useState('')
  const [note, setNote] = useState('')

  const valid = title.trim().length > 0 && date !== ''

  async function save() {
    if (!valid) return
    await db.family.add({
      ...newEnvelope(me, 'C2_shared_ops'),
      kind: 'cp_cal',
      title: title.trim(),
      date,
      // A backwards or equal end date carries no span, so it is simply dropped.
      ...(endDate && endDate > date ? { endDate } : {}),
      ...(time ? { time } : {}),
      category,
      ...(place.trim() ? { place: place.trim() } : {}),
      ...(childId ? { childId } : {}),
      household,
      ...(note.trim() ? { note: note.trim() } : {}),
    } as never)
    onClose()
  }

  return (
    <div className="stack">
      <Field label={t('coparenting.cal.eventTitle')}>
        {(p) => <input {...p} value={title} onChange={(e) => setTitle(e.target.value)} />}
      </Field>
      <Field label={t('coparenting.cal.category')}>
        {(p) => (
          <select {...p} value={category} onChange={(e) => setCategory(e.target.value as CalCategory)}>
            {CAL_CATEGORIES.map((c) => (
              <option key={c} value={c}>{t(`coparenting.cal.cat.${c}` as const)}</option>
            ))}
          </select>
        )}
      </Field>
      <Field label={t('common.date')}>
        {(p) => <input {...p} type="date" value={date} onChange={(e) => setDate(e.target.value)} />}
      </Field>
      <Field label={t('coparenting.cal.endDate')} hint={t('coparenting.cal.endDateHint')}>
        {(p) => <input {...p} type="date" min={date} value={endDate} onChange={(e) => setEndDate(e.target.value)} />}
      </Field>
      <Field label={t('coparenting.cal.time')} hint={t('common.optional')}>
        {(p) => <input {...p} type="time" value={time} onChange={(e) => setTime(e.target.value)} />}
      </Field>
      <Field label={t('coparenting.cal.place')} hint={t('coparenting.cal.placeHint')}>
        {(p) => <input {...p} value={place} onChange={(e) => setPlace(e.target.value)} />}
      </Field>

      <fieldset style={{ border: 0, padding: 0, margin: 0 }} className="stack stack--tight">
        <legend style={{ fontSize: 13, fontWeight: 700, padding: 0 }}>{t('coparenting.cal.household')}</legend>
        <div className="row">
          {CAL_HOUSEHOLDS.map((h) => (
            <button
              key={h}
              type="button"
              aria-pressed={household === h}
              className={household === h ? 'btn btn--sm' : 'btn btn--soft btn--sm'}
              onClick={() => setHousehold(h)}
            >
              {householdLabel(h, names, t)}
            </button>
          ))}
        </div>
      </fieldset>

      {kids.length > 0 && (
        <Field label={t('coparenting.ho.child')} hint={t('common.optional')}>
          {(p) => (
            <select {...p} value={childId} onChange={(e) => setChildId(e.target.value)}>
              <option value="">—</option>
              {kids.map((c) => (
                <option key={c.id} value={c.id}>{c.name}</option>
              ))}
            </select>
          )}
        </Field>
      )}
      <Field label={t('coparenting.cal.note')} hint={t('common.optional')}>
        {(p) => <textarea {...p} rows={2} value={note} onChange={(e) => setNote(e.target.value)} />}
      </Field>

      <div className="row">
        <button className="btn grow" onClick={save} disabled={!valid}>{t('common.save')}</button>
        <button className="btn btn--ghost" onClick={onClose}>{t('common.cancel')}</button>
      </div>
    </div>
  )
}

// ---------------------------------------------------------------------------
// Reimbursement requests (CP11) — split via the finance engine (CP10)
// ---------------------------------------------------------------------------
/**
 * A request to be paid back for a cost already carried. The suggested amount is
 * computed by `childSplit`, which reuses finance/money's `distribute` — the same
 * split engine the household money screen uses — so the figure is arithmetic, not
 * a verdict. Nothing is owed until the other side accepts.
 */
function Reimbursements({
  me,
  t,
  locale,
  names,
  mode,
  expenses,
  requests,
}: Common & {
  names: Record<CaregiverKey, string>
  mode: Mode
  expenses: Cp<'cp_expense'>[]
  requests: Cp<'cp_reimburse'>[]
}) {
  const [open, setOpen] = useState(false)
  const totals = reimburseTotals(requests)
  const sorted = [...requests].sort((a, b) => b.date.localeCompare(a.date))

  return (
    <>
      <Card
        title={t('coparenting.reimb.title')}
        icon="money"
        hint={t('coparenting.reimb.hint')}
        action={
          <button className="btn btn--sm" onClick={() => setOpen(true)}>
            <Icon name="plus" size={16} /> {t('coparenting.reimb.new')}
          </button>
        }
      >
        <div className="row">
          <span className="chip chip--mint">
            {t('coparenting.reimb.owedToMe')}: {formatRupiah(totals.owedToMe, locale)}
          </span>
          <span className="chip chip--blue">
            {t('coparenting.reimb.owedByMe')}: {formatRupiah(totals.owedByMe, locale)}
          </span>
          <span className="chip chip--yellow">
            {t('coparenting.reimb.outgoingPending')}: {formatRupiah(totals.outgoingPending, locale)}
          </span>
          <span className="chip chip--lavender">
            {t('coparenting.reimb.incomingPending')}: {formatRupiah(totals.incomingPending, locale)}
          </span>
        </div>
        {mode.solo && <p className="card__hint">{t('coparenting.reimb.soloHint')}</p>}

        {sorted.length === 0 ? (
          <EmptyState icon="money" title={t('coparenting.reimb.none')} hint={t('coparenting.reimb.noneHint')} />
        ) : (
          <div className="stack">
            {sorted.map((r) => {
              const linked = expenses.find((e) => e.id === r.expenseId)
              return (
                <section key={r.id} className="card card--flat stack stack--tight">
                  <div className="row row--between">
                    <span className="stack stack--tight grow">
                      <strong style={{ fontSize: 14 }}>{r.label}</strong>
                      <span className="card__hint">
                        {whenLabel(r.date, t, locale)} · {formatRupiah(r.amount, locale)}
                      </span>
                      <span className="card__hint">
                        {t('coparenting.reimb.by', { who: names[r.requestedBy] })}
                      </span>
                      {r.receiptRef && (
                        <span className="card__hint">
                          {t('coparenting.reimb.receiptRef')}: {r.receiptRef}
                        </span>
                      )}
                      {linked && (
                        <span className="card__hint">
                          {t('coparenting.reimb.forExpense')}: {linked.label}
                        </span>
                      )}
                      {r.note && !mode.parallel && <span className="card__hint">{r.note}</span>}
                    </span>
                    <span className="chip">{t(`coparenting.reimb.status.${r.status}` as const)}</span>
                    <DeleteButton id={r.id} me={me} t={t} />
                  </div>
                  {canDecide(r) ? (
                    <div className="row">
                      <button
                        className="btn btn--sm"
                        onClick={() =>
                          patch(STORE, r.id, { status: 'diterima', answeredAt: new Date().toISOString() })
                        }
                      >
                        <Icon name="check" size={16} /> {t('coparenting.reimb.accept')}
                      </button>
                      <button
                        className="btn btn--soft btn--sm"
                        onClick={() =>
                          patch(STORE, r.id, { status: 'ditolak', answeredAt: new Date().toISOString() })
                        }
                      >
                        {t('coparenting.reimb.decline')}
                      </button>
                    </div>
                  ) : (
                    r.status === 'diterima' && (
                      <div className="row">
                        <button
                          className="btn btn--soft btn--sm"
                          onClick={() => patch(STORE, r.id, { status: 'dibayar' })}
                        >
                          {t('coparenting.reimb.markPaid')}
                        </button>
                      </div>
                    )
                  )}
                </section>
              )
            })}
          </div>
        )}
      </Card>

      <Sheet open={open} onClose={() => setOpen(false)} title={t('coparenting.reimb.new')}>
        {open && (
          <ReimburseForm
            onClose={() => setOpen(false)}
            me={me}
            t={t}
            names={names}
            mode={mode}
            expenses={expenses}
          />
        )}
      </Sheet>
    </>
  )
}

function ReimburseForm({
  onClose,
  me,
  t,
  names,
  mode,
  expenses,
}: {
  onClose: () => void
  me: string
  t: TFunction
  names: Record<CaregiverKey, string>
  mode: Mode
  expenses: Cp<'cp_expense'>[]
}) {
  const { locale } = useI18n()
  const [label, setLabel] = useState('')
  const [date, setDate] = useState(todayISO())
  const [requestedBy, setRequestedBy] = useState<CaregiverKey>('aku')
  const [amount, setAmount] = useState('')
  const [expenseId, setExpenseId] = useState('')
  const [receiptRef, setReceiptRef] = useState('')
  const [note, setNote] = useState('')
  // CP10 split helper — the finance engine, pointed at two caregivers.
  const [total, setTotal] = useState('')
  const [basis, setBasis] = useState<SplitBasis>('rata')
  const [incAku, setIncAku] = useState('')
  const [incDia, setIncDia] = useState('')

  const n = Math.round(Number(amount))
  const valid = label.trim().length > 0 && Number.isFinite(n) && n > 0

  const totalN = Math.round(Number(total))
  const suggested =
    Number.isFinite(totalN) && totalN > 0
      ? suggestedReimbursement(totalN, basis, requestedBy, incomesFrom(basis, incAku, incDia))
      : 0
  const preview = Number.isFinite(totalN) && totalN > 0 ? childSplit(totalN, basis, incomesFrom(basis, incAku, incDia)) : null

  function pickExpense(id: string) {
    setExpenseId(id)
    const e = expenses.find((x) => x.id === id)
    if (e) {
      if (!label.trim()) setLabel(e.label)
      setTotal(String(e.amount))
      setDate(e.date)
    }
  }

  async function save() {
    if (!valid) return
    await db.family.add({
      ...newEnvelope(me, 'C2_shared_ops'),
      kind: 'cp_reimburse',
      label: label.trim(),
      date,
      amount: n,
      requestedBy,
      ...(expenseId ? { expenseId } : {}),
      ...(receiptRef.trim() ? { receiptRef: receiptRef.trim() } : {}),
      status: 'diajukan',
      ...(note.trim() && !mode.parallel ? { note: note.trim() } : {}),
    } as never)
    onClose()
  }

  return (
    <div className="stack">
      <Field label={t('coparenting.reimb.label')}>
        {(p) => <input {...p} value={label} onChange={(e) => setLabel(e.target.value)} />}
      </Field>
      <CaregiverPicker
        value={requestedBy}
        onChange={setRequestedBy}
        names={names}
        legend={t('coparenting.reimb.requestedBy')}
      />
      <Field label={t('common.date')}>
        {(p) => <input {...p} type="date" value={date} onChange={(e) => setDate(e.target.value)} />}
      </Field>

      {expenses.length > 0 && (
        <Field label={t('coparenting.reimb.forExpense')} hint={t('common.optional')}>
          {(p) => (
            <select {...p} value={expenseId} onChange={(e) => pickExpense(e.target.value)}>
              <option value="">—</option>
              {expenses.map((e) => (
                <option key={e.id} value={e.id}>{e.label}</option>
              ))}
            </select>
          )}
        </Field>
      )}

      {/* CP10: work the amount out through the finance split engine, or type it. */}
      <div className="card card--flat stack stack--tight">
        <Field label={t('coparenting.reimb.totalCost')} hint={t('common.optional')}>
          {(p) => (
            <input {...p} type="number" inputMode="numeric" min={0} value={total} onChange={(e) => setTotal(e.target.value)} />
          )}
        </Field>
        <fieldset style={{ border: 0, padding: 0, margin: 0 }} className="stack stack--tight">
          <legend style={{ fontSize: 13, fontWeight: 700, padding: 0 }}>{t('coparenting.reimb.splitBasis')}</legend>
          <div className="row">
            {SPLIT_BASES.map((b) => (
              <button
                key={b}
                type="button"
                aria-pressed={basis === b}
                className={basis === b ? 'btn btn--sm' : 'btn btn--soft btn--sm'}
                onClick={() => setBasis(b)}
              >
                {t(`coparenting.reimb.basis.${b}` as const)}
              </button>
            ))}
          </div>
        </fieldset>
        {basis === 'penghasilan' && (
          <div className="row">
            <Field label={t('coparenting.reimb.income', { who: names.aku })}>
              {(p) => <input {...p} type="number" inputMode="numeric" min={0} value={incAku} onChange={(e) => setIncAku(e.target.value)} />}
            </Field>
            <Field label={t('coparenting.reimb.income', { who: names.dia })}>
              {(p) => <input {...p} type="number" inputMode="numeric" min={0} value={incDia} onChange={(e) => setIncDia(e.target.value)} />}
            </Field>
          </div>
        )}
        {preview && (
          <>
            <p className="card__hint">
              {names.aku}: {formatRupiah(preview.aku, locale)} · {names.dia}: {formatRupiah(preview.dia, locale)}
            </p>
            <button className="btn btn--soft btn--sm" onClick={() => setAmount(String(suggested))}>
              {t('coparenting.reimb.suggest', { amount: formatRupiah(suggested, locale) })}
            </button>
            <p className="disclaimer">{t('coparenting.reimb.suggestHint')}</p>
          </>
        )}
      </div>

      <Field label={t('coparenting.reimb.amount')}>
        {(p) => (
          <input {...p} type="number" inputMode="numeric" min={0} value={amount} onChange={(e) => setAmount(e.target.value)} />
        )}
      </Field>
      <Field label={t('coparenting.reimb.receiptRef')} hint={t('coparenting.reimb.receiptRefHint')}>
        {(p) => <input {...p} value={receiptRef} onChange={(e) => setReceiptRef(e.target.value)} />}
      </Field>
      {!mode.parallel && (
        <Field label={t('coparenting.reimb.note')} hint={t('common.optional')}>
          {(p) => <textarea {...p} rows={2} value={note} onChange={(e) => setNote(e.target.value)} />}
        </Field>
      )}

      <div className="row">
        <button className="btn grow" onClick={save} disabled={!valid}>{t('common.save')}</button>
        <button className="btn btn--ghost" onClick={onClose}>{t('common.cancel')}</button>
      </div>
    </div>
  )
}

/** Only the income pair matters, and only when splitting by income. */
function incomesFrom(basis: SplitBasis, aku: string, dia: string): Record<CaregiverKey, number> | undefined {
  if (basis !== 'penghasilan') return undefined
  return { aku: Math.max(0, Math.round(Number(aku)) || 0), dia: Math.max(0, Math.round(Number(dia)) || 0) }
}

