// ---------------------------------------------------------------------------
// Third-party access (CP15)
// ---------------------------------------------------------------------------
/**
 * A grant to a grandparent, nanny, or teacher — one child, one capability, per
 * row. Two capabilities is two grants, so a grant can never widen and revoking
 * half is clean. There is no separate login (Rp0, offline, single device): this
 * records the scope, the app honours it at render. See thirdparty.ts.
 */

function ThirdPartyAccess({
  me,
  t,
  locale,
  names,
  kids,
  grants,
}: Common & {
  names: Record<CaregiverKey, string>
  kids: Cp<'child'>[]
  grants: Cp<'cp_thirdparty'>[]
}) {
  void locale
  void names
  const [open, setOpen] = useState(false)
  const active = grants.filter((g) => g.active)
  const revoked = grants.filter((g) => !g.active)

  const row = (g: Cp<'cp_thirdparty'>) => {
    const child = kids.find((k) => k.id === g.childId)
    return (
      <section key={g.id} className="card card--flat stack stack--tight">
        <div className="row row--between">
          <strong style={{ fontSize: 14 }}>{g.label}</strong>
          <DeleteButton id={g.id} me={me} t={t} />
        </div>
        <span className="row">
          <span className="chip">{t(`coparenting.tp.role.${g.role}` as const)}</span>
          {child && <span className="chip">{child.name}</span>}
          <span className="chip chip--blue">{t(`coparenting.tp.cap.${g.capability}` as const)}</span>
        </span>
        <div className="row">
          {g.active ? (
            <button className="btn btn--soft btn--sm" onClick={() => patch(STORE, g.id, { active: false })}>
              {t('coparenting.tp.revoke')}
            </button>
          ) : (
            <button className="btn btn--soft btn--sm" onClick={() => patch(STORE, g.id, { active: true })}>
              {t('coparenting.tp.reactivate')}
            </button>
          )}
        </div>
      </section>
    )
  }

  return (
    <>
      <Card
        title={t('coparenting.tp.title')}
        icon="shield"
        hint={t('coparenting.tp.hint')}
        action={
          kids.length > 0 ? (
            <button className="btn btn--sm" onClick={() => setOpen(true)}>
              <Icon name="plus" size={16} /> {t('coparenting.tp.new')}
            </button>
          ) : undefined
        }
      >
        <p className="card__hint">{t('coparenting.tp.scopeNote')}</p>
        {kids.length === 0 ? (
          <EmptyState icon="family" title={t('coparenting.needChild')} hint={t('coparenting.tp.noneHint')} />
        ) : grants.length === 0 ? (
          <EmptyState icon="shield" title={t('coparenting.tp.none')} hint={t('coparenting.tp.noneHint')} />
        ) : (
          <div className="stack">
            {active.map(row)}
            {revoked.length > 0 && (
              <>
                <p className="card__hint">{t('coparenting.tp.revokedHeading')}</p>
                {revoked.map(row)}
              </>
            )}
          </div>
        )}
      </Card>

      <Sheet open={open} onClose={() => setOpen(false)} title={t('coparenting.tp.new')}>
        {open && <ThirdPartyForm onClose={() => setOpen(false)} me={me} t={t} kids={kids} />}
      </Sheet>
    </>
  )
}

