/**
 * Child profile maths (CP7).
 *
 * The profile is owned jointly: both parents may edit the same row, which is
 * only fair if both can see what changed. `diffChild` is what makes that
 * possible — it turns "someone saved the form" into a list of specific field
 * moves, and it returns *nothing* when nothing actually moved, so an opened-and-
 * closed form never writes a fake history entry.
 *
 * No copy here: field names come back as keys and the component translates them.
 */

/** A date that matters, entered by a parent. Never seeded from anywhere. */
export interface KeyDate {
  label: string
  /** yyyy-MM-dd. */
  date: string
}

export const CHILD_FIELDS = [
  'name',
  'birthDate',
  'school',
  'clothingSize',
  'shoeSize',
  'emergencyContact',
  'pickupAllowed',
  'dates',
  'note',
] as const
export type ChildField = (typeof CHILD_FIELDS)[number]

export interface ChildProfileLike {
  name?: string
  birthDate?: string
  school?: string
  clothingSize?: string
  shoeSize?: string
  emergencyContact?: string
  pickupAllowed?: string
  dates?: KeyDate[]
  note?: string
}

export interface ChildChange {
  field: ChildField
  /** Absent means the field was empty before. */
  from?: string
  /** Absent means it was cleared. */
  to?: string
}

/** yyyy-MM-dd, and a real one — `2026-02-31` is not a date anybody has. */
export function isDate(raw: string | undefined): boolean {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(raw ?? '')) return false
  return new Date(`${raw}T00:00:00Z`).toISOString().slice(0, 10) === raw
}

/** Drops rows with no label or no usable date, then sorts by date. */
export function sortKeyDates(list: readonly KeyDate[] | undefined): KeyDate[] {
  return (list ?? [])
    .filter((d) => d.label.trim() !== '' && isDate(d.date))
    .map((d) => ({ label: d.label.trim(), date: d.date }))
    .sort((a, b) => a.date.localeCompare(b.date) || a.label.localeCompare(b.label))
}

/** The next key date on or after `today`, or nothing. A reminder, not a countdown. */
export function nextKeyDate(list: readonly KeyDate[] | undefined, today: string): KeyDate | undefined {
  return sortKeyDates(list).find((d) => d.date >= today)
}

/** One line per date so a change entry reads as text rather than as JSON. */
export function formatKeyDates(list: readonly KeyDate[] | undefined): string {
  return sortKeyDates(list)
    .map((d) => `${d.date} ${d.label}`)
    .join('\n')
}

function value(rec: ChildProfileLike, field: ChildField): string {
  if (field === 'dates') return formatKeyDates(rec.dates)
  return (rec[field] as string | undefined)?.trim() ?? ''
}

/**
 * Field-by-field difference between the saved record and what the form holds.
 *
 * Empty and absent are the same thing here: clearing a field the user never
 * filled is not a change, and would otherwise write a history row on every save.
 */
export function diffChild(before: ChildProfileLike | null, after: ChildProfileLike): ChildChange[] {
  const out: ChildChange[] = []
  for (const field of CHILD_FIELDS) {
    const from = before ? value(before, field) : ''
    const to = value(after, field)
    if (from === to) continue
    out.push({ field, ...(from ? { from } : {}), ...(to ? { to } : {}) })
  }
  return out
}

/** Whole years, in the local calendar sense. Undefined for a birth date in the future. */
export function ageInYears(birthDate: string, today: string): number | undefined {
  if (!isDate(birthDate) || !isDate(today) || birthDate > today) return undefined
  let years = Number(today.slice(0, 4)) - Number(birthDate.slice(0, 4))
  if (today.slice(5) < birthDate.slice(5)) years--
  return years
}
