import { useState } from 'react'
import { Icon } from '@/design-system/Icon'
import { EmptyState, Field, PARTNER_VISIBILITY_OPTIONS, Sheet, VisibilityBadge } from '@/components/ui'
import { db, newEnvelope, setVisibility, softDelete } from '@/db/db'
import type { Visibility } from '@/types/domain'
import type { MessageKey, TFunction } from '@/i18n'
import { fmtDate } from '@/i18n/format'
import { todayISO, type CaregiverKey } from './schedule'
import { sortKeyDates, type KeyDate } from './childProfile'
import { ENTRY_UNIT, HEALTH_ENTRY_TYPES, isMeasurement, measureChange, sortEntries, type HealthEntryType } from './health'
import type { Cp } from './types'

/**
 * The parts of the child screen that CP7 and CP8 added: the key-date editor,
 * the change history, and the health record list.
 *
 * They live here rather than in `Index.tsx` only because that file is already
 * long. Everything reads and writes through the same store and the same privacy
 * gate as the rest of the module.
 */

const STORE = 'family' as const

/** Local, because importing it from `Index.tsx` would make the two files circular. */
function Remove({ id, me, label }: { id: string; me: string; label: string }) {
  return (
    <button className="btn btn--ghost btn--sm btn--icon" onClick={() => softDelete(STORE, id, me)}>
      <Icon name="close" size={16} label={label} />
    </button>
  )
}

// ---------------------------------------------------------------------------
// CP7 — key dates
// ---------------------------------------------------------------------------

/**
 * A list of dates the parents type in themselves.
 *
 * There is no picker of public holidays or school terms behind this, on purpose:
 * the app has no source it could cite for those, and a wrong date here would
 * send somebody to a locked school gate.
 */
export function KeyDatesEditor({
  value,
  onChange,
  t,
}: {
  value: KeyDate[]
  onChange: (next: KeyDate[]) => void
  t: TFunction
}) {
  const set = (i: number, patch: Partial<KeyDate>) =>
    onChange(value.map((d, j) => (j === i ? { ...d, ...patch } : d)))

  return (
    <fieldset style={{ border: 0, padding: 0, margin: 0 }} className="stack stack--tight">
      <legend style={{ fontSize: 13, fontWeight: 700, padding: 0 }}>{t('coparenting.child.dates')}</legend>
      <p className="card__hint">{t('coparenting.child.datesHint')}</p>
      {value.map((d, i) => (
        <div key={i} className="row">
          <input
            type="date"
            aria-label={t('coparenting.health.entryDate')}
            value={d.date}
            style={{ width: 'auto' }}
            onChange={(e) => set(i, { date: e.target.value })}
          />
          <input
            className="grow"
            aria-label={t('coparenting.child.dateLabel')}
            value={d.label}
            onChange={(e) => set(i, { label: e.target.value })}
          />
          <button
            type="button"
            className="btn btn--ghost btn--sm btn--icon"
            onClick={() => onChange(value.filter((_, j) => j !== i))}
          >
            <Icon name="close" size={16} label={t('coparenting.child.dateRemove')} />
          </button>
        </div>
      ))}
      <div className="row">
        <button
          type="button"
          className="btn btn--soft btn--sm"
          onClick={() => onChange([...value, { label: '', date: todayISO() }])}
        >
          <Icon name="plus" size={16} /> {t('coparenting.child.dateAdd')}
        </button>
      </div>
    </fieldset>
  )
}

export function KeyDateList({ dates, t, locale }: { dates: KeyDate[] | undefined; t: TFunction; locale: 'id' | 'en' }) {
  const sorted = sortKeyDates(dates)
  if (sorted.length === 0) return null
  return (
    <>
      <strong style={{ fontSize: 13 }}>{t('coparenting.child.dates')}</strong>
      <ul className="list">
        {sorted.map((d) => (
          <li key={`${d.date}-${d.label}`} className="list__item">
            <Icon name="date" size={16} />
            <span className="grow">{d.label}</span>
            <span className="card__hint">{fmtDate(d.date, 'd MMM yyyy', locale)}</span>
          </li>
        ))}
      </ul>
    </>
  )
}

// ---------------------------------------------------------------------------
// CP7 — change history
// ---------------------------------------------------------------------------

/**
 * Who changed what, and when.
 *
 * The row is owned by whoever wrote it, so "who" comes from the envelope rather
 * than from anything the writer could set. Nothing is counted: this is a list of
 * edits, not a tally of who edits more.
 */
export function ChangeHistory({
  changes,
  me,
  names,
  t,
  locale,
}: {
  changes: Cp<'cp_child_change'>[]
  me: string
  names: Record<CaregiverKey, string>
  t: TFunction
  locale: 'id' | 'en'
}) {
  const sorted = [...changes].sort((a, b) => b.createdAt.localeCompare(a.createdAt))
  return (
    <>
      <strong style={{ fontSize: 13 }}>{t('coparenting.child.history')}</strong>
      <p className="card__hint">{t('coparenting.child.historyHint')}</p>
      {sorted.length === 0 ? (
        <p className="card__hint">{t('coparenting.child.historyNone')}</p>
      ) : (
        <ul className="list">
          {sorted.slice(0, 20).map((c) => {
            const field = t(`coparenting.child.field.${c.field}` as MessageKey)
            const key: MessageKey = c.to
              ? c.from
                ? 'coparenting.child.change.moved'
                : 'coparenting.child.change.set'
              : 'coparenting.child.change.cleared'
            return (
              <li key={c.id} className="list__item">
                <span className="grow stack stack--tight">
                  <span>{t(key, { field, from: c.from ?? '', to: c.to ?? '' })}</span>
                  <span className="card__hint">
                    {t('coparenting.child.changeBy', {
                      name: c.ownerProfileId === me ? names.aku : names.dia,
                      date: fmtDate(c.createdAt.slice(0, 10), 'd MMM yyyy', locale),
                    })}
                  </span>
                </span>
              </li>
            )
          })}
        </ul>
      )}
    </>
  )
}

// ---------------------------------------------------------------------------
// CP8 — health record entries
// ---------------------------------------------------------------------------

export function HealthEntries({
  child,
  entries,
  me,
  t,
  locale,
}: {
  child: Cp<'child'>
  entries: Cp<'cp_health_entry'>[]
  me: string
  t: TFunction
  locale: 'id' | 'en'
}) {
  const [open, setOpen] = useState(false)
  const mine = sortEntries(entries.filter((e) => e.childId === child.id))

  return (
    <>
      <div className="row row--between">
        <strong style={{ fontSize: 13 }}>{t('coparenting.health.entries')}</strong>
        <button className="btn btn--soft btn--sm" onClick={() => setOpen(true)}>
          <Icon name="plus" size={16} /> {t('coparenting.health.entryAdd')}
        </button>
      </div>
      <p className="card__hint">{t('coparenting.health.entriesHint')}</p>

      {mine.length === 0 ? (
        <EmptyState
          icon="health"
          title={t('coparenting.health.entryNone')}
          hint={t('coparenting.health.entryNoneHint')}
        />
      ) : (
        <>
          {/* Descriptive only: the difference between two numbers the user typed,
              with no expected value and no comment on what it means. */}
          {HEALTH_ENTRY_TYPES.filter(isMeasurement).map((type) => {
            const c = measureChange(mine, type)
            if (!c) return null
            return (
              <p key={type} className="card__hint">
                {t(`coparenting.health.type.${type}` as MessageKey)}:{' '}
                {t('coparenting.health.changeLine', {
                  from: c.from,
                  to: c.to,
                  unit: c.unit,
                  days: c.days,
                })}
              </p>
            )
          })}

          <ul className="list">
            {mine.map((e) => (
              <li key={e.id} className="list__item">
                <span className="grow stack stack--tight">
                  <strong style={{ fontSize: 13 }}>
                    {t(`coparenting.health.type.${e.entryType}` as MessageKey)}
                    {e.value ? `: ${e.value}${ENTRY_UNIT[e.entryType] ? ` ${ENTRY_UNIT[e.entryType]}` : ''}` : ''}
                  </strong>
                  <span className="card__hint">{fmtDate(e.date, 'd MMM yyyy', locale)}</span>
                  {e.note && <span className="card__hint">{e.note}</span>}
                </span>
                <VisibilityBadge visibility={e.visibility} />
                {/* Only the owner may widen a health record; `setVisibility` refuses anyone else. */}
                {e.ownerProfileId === me && (
                  <label className="row" style={{ gap: 4 }}>
                    <span className="visually-hidden">{t('common.whoCanSee')}</span>
                    <select
                      value={e.visibility}
                      style={{ width: 'auto', minHeight: 36, fontSize: 12 }}
                      onChange={(ev) => setVisibility(STORE, e.id, me, ev.target.value as Visibility)}
                    >
                      {PARTNER_VISIBILITY_OPTIONS.map((v) => (
                        <option key={v} value={v}>
                          {t(`vis.opt.${v}` as MessageKey)}
                        </option>
                      ))}
                    </select>
                  </label>
                )}
                <Remove id={e.id} me={me} label={t('coparenting.delete')} />
              </li>
            ))}
          </ul>
        </>
      )}
      <p className="disclaimer">{t('coparenting.health.noVerdict')}</p>

      <Sheet open={open} onClose={() => setOpen(false)} title={t('coparenting.health.entryAdd')}>
        {open && <HealthEntryForm childId={child.id} me={me} t={t} onClose={() => setOpen(false)} />}
      </Sheet>
    </>
  )
}

function HealthEntryForm({
  childId,
  me,
  t,
  onClose,
}: {
  childId: string
  me: string
  t: TFunction
  onClose: () => void
}) {
  const [entryType, setEntryType] = useState<HealthEntryType>('berat')
  const [date, setDate] = useState(todayISO())
  const [value, setValue] = useState('')
  const [note, setNote] = useState('')
  const unit = ENTRY_UNIT[entryType]

  async function save() {
    if (!value.trim()) return
    // C4 — private by default, exactly like the rest of the health record. The
    // owner widens it afterwards, one entry at a time, or not at all.
    await db.family.add({
      ...newEnvelope(me, 'C4_health'),
      kind: 'cp_health_entry',
      childId,
      entryType,
      date,
      value: value.trim(),
      ...(note.trim() ? { note: note.trim() } : {}),
    } as never)
    onClose()
  }

  return (
    <div className="stack">
      <p className="card__hint">{t('coparenting.health.entryPrivate')}</p>
      <Field label={t('coparenting.health.entryType')}>
        {(p) => (
          <select {...p} value={entryType} onChange={(e) => setEntryType(e.target.value as HealthEntryType)}>
            {HEALTH_ENTRY_TYPES.map((k) => (
              <option key={k} value={k}>
                {t(`coparenting.health.type.${k}` as MessageKey)}
              </option>
            ))}
          </select>
        )}
      </Field>
      <Field label={t('coparenting.health.entryDate')}>
        {(p) => <input {...p} type="date" value={date} onChange={(e) => setDate(e.target.value)} />}
      </Field>
      <Field
        label={t('coparenting.health.entryValue')}
        hint={unit ? t('coparenting.health.entryValueNumber', { unit }) : t('coparenting.health.entryValueHint')}
      >
        {(p) =>
          unit ? (
            <input {...p} inputMode="decimal" value={value} onChange={(e) => setValue(e.target.value)} />
          ) : (
            <input {...p} value={value} onChange={(e) => setValue(e.target.value)} />
          )
        }
      </Field>
      <Field label={t('coparenting.health.entryNote')} hint={t('common.optional')}>
        {(p) => <textarea {...p} rows={2} value={note} onChange={(e) => setNote(e.target.value)} />}
      </Field>
      <p className="disclaimer">{t('coparenting.health.noVerdict')}</p>
      <div className="row">
        <button className="btn grow" onClick={save} disabled={!value.trim()}>
          {t('common.save')}
        </button>
        <button className="btn btn--ghost" onClick={onClose}>
          {t('common.cancel')}
        </button>
      </div>
    </div>
  )
}
