import type { Owned } from '@/types/domain'
import type { CaregiverKey, ExpenseStatus, SwapStatus } from './schedule'
import type { ChildField, KeyDate } from './childProfile'
import type { HealthEntryType } from './health'
import type { CalCategory, CalHousehold } from './calendar'
import type { ReimburseStatus } from './reimburse'
import type { DecidedBy } from './decisions'
import type { ContactChannel } from './contactlog'
import type { ThirdPartyCapability, ThirdPartyRole } from './thirdparty'

/**
 * Co-parenting records.
 *
 * These live in the existing `family` store rather than a store of their own:
 * `db.ts` has no `coparenting` table and is off-limits to this feature (noted in
 * the handover). `family` already indexes `kind`, `childId` and `date`, is in
 * `OWNED_STORES`, and `backup.ts` only asserts `kind` on it — so backup, audit,
 * visibility and unpair all cover these rows unchanged. Every kind here is
 * prefixed `cp_` so it cannot collide with a future `FamilyRecord` variant.
 *
 * `child` is the one exception: it deliberately reuses the existing kind so a
 * child entered in Keluarga is the same child here, with optional extra fields
 * that Keluarga simply ignores. Two child lists would be worse than a wide row.
 */

export type CoparentKind = CoparentRecord['kind']

/** Descriptive, never ranked — a child is not scored on handover. */
export type ChildMood = 'ceria' | 'biasa' | 'rewel' | 'sedih' | 'kurang_enak_badan'
export const CHILD_MOODS: readonly ChildMood[] = ['ceria', 'biasa', 'rewel', 'sedih', 'kurang_enak_badan']

export type SwapReason = 'kerjaan' | 'sakit' | 'acara_keluarga' | 'perjalanan' | 'lainnya'
export const SWAP_REASONS: readonly SwapReason[] = ['kerjaan', 'sakit', 'acara_keluarga', 'perjalanan', 'lainnya']

export type TopicCategory = 'jadwal' | 'kesehatan' | 'sekolah' | 'uang' | 'barang' | 'lainnya'
export const TOPIC_CATEGORIES: readonly TopicCategory[] = [
  'jadwal',
  'kesehatan',
  'sekolah',
  'uang',
  'barang',
  'lainnya',
]

export type TopicStatus = 'diajukan' | 'dijawab' | 'ditutup'

/**
 * The closed list of things one side can ask the other for (CP6).
 *
 * In parallel parenting mode this *replaces* the free-text question: you pick a
 * request, not write a paragraph. The list is deliberately short and boring —
 * every entry is a logistics decision with a yes/no answer, so nothing here can
 * carry an opinion about the other parent.
 */
export type TopicAsk =
  | 'tukar_jadwal'
  | 'jemput_antar'
  | 'ganti_lokasi_serah'
  | 'izin_perjalanan'
  | 'biaya_tambahan'
  | 'barang_anak'
  | 'info_sekolah'
  | 'info_kesehatan'
export const TOPIC_ASKS: readonly TopicAsk[] = [
  'tukar_jadwal',
  'jemput_antar',
  'ganti_lokasi_serah',
  'izin_perjalanan',
  'biaya_tambahan',
  'barang_anak',
  'info_sekolah',
  'info_kesehatan',
]

/** The three answers a structured request can get. No free text, on purpose. */
export type TopicAnswerChoice = 'ya' | 'tidak' | 'perlu_waktu'
export const TOPIC_ANSWER_CHOICES: readonly TopicAnswerChoice[] = ['ya', 'tidak', 'perlu_waktu']

/** File *metadata* only. The app stores no attachments anywhere — see HouseholdDocument. */
export interface ProofMeta {
  fileName: string
  sizeBytes: number
  mimeType: string
  /** File's own last-modified date, so the note still means something later. */
  fileDate?: string
}

export type CoparentRecord = Owned<
  | {
      kind: 'child'
      name: string
      birthDate: string
      note?: string
      // Logistics (C2). Health lives in `cp_health` so it can stay private.
      school?: string
      emergencyContact?: string
      /** Free text, one per line. Never a lookup, never a suggestion. */
      pickupAllowed?: string
      /** CP7. Sizes are what the other household actually needs to buy clothes. */
      clothingSize?: string
      shoeSize?: string
      /**
       * CP7. Dates that matter beyond the birthday — first day of school, a
       * passport expiry, the day a term starts. Entered by the parents, never
       * seeded: this app ships no holiday calendar it cannot cite.
       */
      dates?: KeyDate[]
    }
  | {
      /**
       * CP7 change history: one row per field that actually changed.
       *
       * This is *user-facing* history, which is why it holds the old and new
       * value. It is not the audit log — `logAudit` still records only that a
       * change happened. A jointly-owned profile that either parent can edit is
       * only safe if both can see what moved and who moved it.
       */
      kind: 'cp_child_change'
      childId: string
      field: ChildField
      from?: string
      to?: string
    }
  | {
      /**
       * CP8. A health *record*, not a health opinion: a dated line saying what
       * was measured, given, or attended. There is no diagnosis field and no
       * advice anywhere near it — the app records, the clinic decides.
       *
       * Owned C4 like `cp_health`, so it is private until the owner widens it.
       */
      kind: 'cp_health_entry'
      childId: string
      entryType: HealthEntryType
      date: string
      /** What it was: a number for measurements, a name for a shot or a medicine. */
      value?: string
      note?: string
    }
  | {
      kind: 'cp_health'
      childId: string
      bloodType?: string
      allergies?: string
      /** An identifying number on a possibly-shared device — warned about in the UI. */
      bpjs?: string
      doctor?: string
      note?: string
    }
  | {
      kind: 'cp_rota'
      label: string
      anchorDate: string
      days: CaregiverKey[]
      active: boolean
    }
  | {
      kind: 'cp_swap'
      date: string
      /**
       * Last day of a multi-day *exception* (mudik, hospital stay, a school
       * holiday one side travels for). A request with no `untilDate` is the
       * single-day swap it always was, so old rows keep their meaning.
       */
      untilDate?: string
      counterDate?: string
      askedBy: CaregiverKey
      reason: SwapReason
      /** Only offered outside parallel mode; structured reason is always required. */
      note?: string
      status: SwapStatus
      answeredAt?: string
    }
  | {
      kind: 'cp_actual'
      date: string
      caregiver: CaregiverKey
      hours?: number
      note?: string
    }
  | {
      kind: 'cp_handover'
      date: string
      /** Local clock time, HH:mm. Optional — "some time on Tuesday" is honest too. */
      time?: string
      /** Free text where the hand-off happened. Never a lookup, never a map, never
       *  a coordinate: this app does no location of any kind. */
      place?: string
      childId?: string
      /** Who is handing over. The receiver is the other slot. */
      from: CaregiverKey
      /**
       * When each side ticked the card (ISO timestamp), or absent.
       *
       * Two independent flags rather than one `confirmed` boolean, because the
       * point of CP2 is that a card can sit half-ticked without that being
       * anybody's fault. Absent is a normal state, not a failure.
       */
      confirmedByAku?: string
      confirmedByDia?: string
      condition?: string
      mood?: ChildMood
      sleep?: string
      lastMeal?: string
      lastMedicine?: string
      homework?: string
      /** One item per line. */
      broughtItems?: string
      returnItems?: string
      pocketMoney?: number
    }
  | {
      kind: 'cp_expense'
      label: string
      date: string
      amount: number
      /** My share of the cost, 0..1. */
      myShare: number
      paidBy: CaregiverKey
      childId?: string
      status: ExpenseStatus
      proof?: ProofMeta
      note?: string
    }
  | {
      kind: 'cp_topic'
      category: TopicCategory
      /**
       * Free-text pair, used outside parallel mode. Optional since CP6: in
       * parallel mode a request carries `ask` instead, and there is no box to
       * type a subject or a paragraph into.
       */
      subject?: string
      /** What is actually being asked — one decision, not a conversation. */
      question?: string
      /** Parallel mode: the structured request, picked from a closed list. */
      ask?: TopicAsk
      /** Only meaningful for `ask: 'biaya_tambahan'`. Rupiah, whole numbers. */
      askAmount?: number
      neededBy?: string
      answer?: string
      /** Parallel mode: the structured answer. Free text never appears here. */
      answerChoice?: TopicAnswerChoice
      status: TopicStatus
    }
  | {
      /**
       * CP9. A school or activity entry both households share. Never seeded —
       * the app ships no term dates or holiday list it cannot cite, so every
       * row is one a parent typed. `place` is free text, never a lookup or a map.
       */
      kind: 'cp_cal'
      title: string
      date: string
      /** Last day of a span (a camp, a holiday week). Absent means a single day. */
      endDate?: string
      /** Local clock time, HH:mm. Optional — "some time that day" is honest. */
      time?: string
      category: CalCategory
      place?: string
      childId?: string
      /** Which side takes the child, or both. A label, not a profile. */
      household: CalHousehold
      note?: string
    }
  | {
      /**
       * CP11. A request to be paid back for a cost one side already carried.
       * The suggested amount can come from CP10's finance-engine split, but the
       * request still moves through accept/decline — nothing is owed until the
       * other side agrees.
       */
      kind: 'cp_reimburse'
      label: string
      date: string
      amount: number
      requestedBy: CaregiverKey
      /**
       * A pointer to the receipt — a number, a shop, a note. Never the file:
       * TemuDua stores no attachments, and a receipt with a name on it is
       * somebody's data.
       */
      receiptRef?: string
      /** Optional link to the `cp_expense` this claims a share of. */
      expenseId?: string
      status: ReimburseStatus
      answeredAt?: string
      note?: string
    }
  | {
      /**
       * CP12. One line in the shared decisions log: what was agreed, when, by
       * whom. Append-only — the screen offers no edit and no delete, so a logged
       * decision stays the fact it was. Not the audit log: this is user-facing,
       * so it holds the actual agreement text.
       */
      kind: 'cp_decision'
      date: string
      summary: string
      decidedBy: DecidedBy
      category: TopicCategory
      childId?: string
      note?: string
    }
  | {
      /**
       * CP13. That a contact happened — never its content. The record has no
       * free-text body by construction: there is nowhere to store a message, so
       * the log can never become a place one parent's words about the other are
       * kept and re-read. `channel`, `initiatedBy`, and `connected` are metadata,
       * not content.
       */
      kind: 'cp_contact'
      date: string
      /** Local clock time, HH:mm. Optional. */
      time?: string
      channel: ContactChannel
      /** Who reached out. The other slot is the one reached. */
      initiatedBy: CaregiverKey
      /** Whether the contact actually connected, or was an unanswered attempt. */
      connected: boolean
      childId?: string
    }
  | {
      /**
       * CP15. A grant of access to a third party (grandparent, nanny, teacher),
       * scoped to exactly one child and one capability. Two capabilities is two
       * rows, never one row with two flags, so a grant can never quietly widen and
       * revoking half is a clean act. `label` is the owner's own name for the
       * person; there is no login here — this records the scope, the app enforces
       * it at render (see thirdparty.ts for the documented gap).
       */
      kind: 'cp_thirdparty'
      /** The owner's label for the person. Their own contact, their own words. */
      label: string
      role: ThirdPartyRole
      childId: string
      capability: ThirdPartyCapability
      /** Revoked grants stay on file but permit nothing. */
      active: boolean
    }
>

export type Cp<K extends CoparentKind> = Extract<CoparentRecord, { kind: K }>

/** Non-owned settings row (`db.settings`), so no envelope and nothing to share. */
export interface CoparentSetup {
  /** What to call the other parent on screen. Blank is fine — Solo Mode works. */
  otherParentLabel: string
  /** Parallel parenting: structured topic requests only, no free-text messages. */
  parallel: boolean
}

export const SETUP_KEY = 'coparenting.setup'
export const DEFAULT_SETUP: CoparentSetup = { otherParentLabel: '', parallel: false }
